/**
 * FreeWire Phase 5 - AI 노드 자동 생성기
 *
 * 텍스트 한 줄 → 노드 그래프 JSON 자동 생성
 *
 * 동작 방식:
 *   1. IntentParser: 자연어 → 의도 파악 (키워드 + 패턴)
 *   2. TemplateEngine: 의도 → 노드 배치 계획
 *   3. LayoutEngine: 노드 위치 자동 계산 (겹침 방지)
 *   4. (선택) LLM 브릿지: 로컬 서버 or Claude API 연동
 */

'use strict';

// ─── 노드 팩토리 ─────────────────────────────────────────────────

let _idCtr = 1;
const uid = () => `ai-${_idCtr++}`;

const NODE = {
  button: (label = '버튼', variant = 'primary') => ({
    id: uid(), type: 'component', subtype: 'button', label: `버튼[${label}]`,
    inputs: [{ name: 'props', portType: 'data' }, { name: 'onClick', portType: 'logic' }],
    outputs: [{ name: 'element', portType: 'component' }],
    props: { label, variant },
  }),

  text: (content = '텍스트', tag = 'p') => ({
    id: uid(), type: 'component', subtype: 'text', label: `텍스트[${content.slice(0,8)}]`,
    inputs: [{ name: 'content', portType: 'data' }],
    outputs: [{ name: 'element', portType: 'component' }],
    props: { content, tag },
  }),

  input: (placeholder = '입력', type = 'text') => ({
    id: uid(), type: 'component', subtype: 'input', label: `입력[${placeholder}]`,
    inputs: [{ name: 'value', portType: 'data' }, { name: 'onChange', portType: 'logic' }],
    outputs: [{ name: 'element', portType: 'component' }, { name: 'value', portType: 'data' }],
    props: { placeholder, type },
  }),

  card: (title = '카드') => ({
    id: uid(), type: 'component', subtype: 'card', label: `카드[${title}]`,
    inputs: [{ name: 'title', portType: 'data' }, { name: 'children', portType: 'component' }],
    outputs: [{ name: 'element', portType: 'component' }],
    props: { title },
  }),

  container: (direction = 'column') => ({
    id: uid(), type: 'component', subtype: 'container', label: `컨테이너`,
    inputs: [{ name: 'children', portType: 'component' }],
    outputs: [{ name: 'element', portType: 'component' }],
    props: { direction, gap: '12px' },
  }),

  state: (name = 'value', initial = '0') => ({
    id: uid(), type: 'data', subtype: 'state', label: `상태[${name}]`,
    inputs: [{ name: 'set', portType: 'data' }],
    outputs: [{ name: 'value', portType: 'data' }],
    props: { name, initial },
  }),

  constant: (value = '', valueType = 'string') => ({
    id: uid(), type: 'data', subtype: 'const', label: `상수`,
    inputs: [],
    outputs: [{ name: 'value', portType: 'data' }],
    props: { value, valueType },
  }),

  array: (items = '[]') => ({
    id: uid(), type: 'data', subtype: 'array', label: `배열`,
    inputs: [],
    outputs: [{ name: 'items', portType: 'data' }],
    props: { items },
  }),

  handler: (name = 'handleClick') => ({
    id: uid(), type: 'logic', subtype: 'handler', label: `핸들러[${name}]`,
    inputs: [{ name: 'action', portType: 'logic' }],
    outputs: [{ name: 'handler', portType: 'logic' }],
    props: { name },
  }),

  setState: (target = 'value') => ({
    id: uid(), type: 'logic', subtype: 'setState', label: `setState[${target}]`,
    inputs: [{ name: 'trigger', portType: 'event' }, { name: 'value', portType: 'data' }],
    outputs: [{ name: 'done', portType: 'event' }],
    props: { target },
  }),

  condition: (operator = '==', value = 'true') => ({
    id: uid(), type: 'logic', subtype: 'condition', label: `조건`,
    inputs: [{ name: 'condition', portType: 'data' }],
    outputs: [{ name: 'true', portType: 'logic' }, { name: 'false', portType: 'logic' }],
    props: { operator, value },
  }),
};

// ─── 의도 파서 ────────────────────────────────────────────────────

class IntentParser {
  parse(text) {
    const t = text.toLowerCase().trim();

    // 1) 직접 패턴
    for (const [pattern, intent] of PATTERNS) {
      if (pattern.test(t)) return { ...intent, raw: text };
    }

    // 2) 키워드 추출로 복합 의도
    const keywords = this._extractKeywords(t);
    return this._buildFromKeywords(keywords, text);
  }

  _extractKeywords(t) {
    const kw = { components: [], data: [], logic: [], style: 'column', title: null };

    // 제목
    const titleMatch = t.match(/["']([^"']+)["']/) || t.match(/제목[은이]?\s*(.+?)(?:\s+|$)/);
    if (titleMatch) kw.title = titleMatch[1];

    // 컴포넌트
    if (/(버튼|button|클릭|submit|제출|확인|취소|저장|삭제|추가)/.test(t)) kw.components.push('button');
    if (/(텍스트|text|제목|title|label|표시|출력)/.test(t)) kw.components.push('text');
    if (/(입력|input|필드|field|이메일|email|비밀번호|password|이름|name|검색|search)/.test(t)) kw.components.push('input');
    if (/(카드|card)/.test(t)) kw.components.push('card');
    if (/(리스트|list|목록|항목)/.test(t)) kw.components.push('list');

    // 데이터
    if (/(상태|state|카운트|count)/.test(t)) kw.data.push('state');
    if (/(배열|array|list|목록|아이템)/.test(t)) kw.data.push('array');

    // 로직
    if (/(핸들러|클릭|이벤트|handler|event|onClick)/.test(t)) kw.logic.push('handler');
    if (/(조건|if|else|분기)/.test(t)) kw.logic.push('condition');

    // 레이아웃
    if (/(가로|row|수평|horizontal)/.test(t)) kw.style = 'row';

    return kw;
  }

  _buildFromKeywords(kw, raw) {
    // 컴포넌트가 없으면 일반 텍스트로
    if (kw.components.length === 0 && kw.data.length === 0) {
      return { type: 'generic', label: raw, raw };
    }
    return { type: 'custom', keywords: kw, raw };
  }
}

// 고정 패턴
const PATTERNS = [
  [/로그인|login|sign.?in/, { type: 'login' }],
  [/회원가입|register|sign.?up/, { type: 'register' }],
  [/카운터|counter|숫자\s*세기/, { type: 'counter' }],
  [/검색|search/, { type: 'search' }],
  [/(할일|todo|task)\s*(리스트|list|목록)?/, { type: 'todo' }],
  [/(프로필|profile)\s*(카드|card)?/, { type: 'profile-card' }],
  [/(댓글|comment)\s*(폼|form)?/, { type: 'comment-form' }],
  [/(결제|payment|checkout)\s*(폼|form)?/, { type: 'checkout' }],
  [/(설정|setting|config)\s*(폼|form|페이지)?/, { type: 'settings' }],
  [/(대시보드|dashboard)/, { type: 'dashboard' }],
  [/(모달|modal|팝업|popup)/, { type: 'modal' }],
  [/네비게이션|navbar|nav\s*bar/, { type: 'navbar' }],
  [/버튼/, { type: 'single-button' }],
  [/카드/, { type: 'single-card' }],
  [/(입력|input)\s*(폼|form)/, { type: 'input-form' }],
];

// ─── 템플릿 엔진 ──────────────────────────────────────────────────

class TemplateEngine {
  generate(intent) {
    const gen = TEMPLATES[intent.type];
    if (gen) return gen(intent);

    // 커스텀 키워드 기반
    if (intent.type === 'custom') return this._generateCustom(intent);

    // 폴백: 단순 텍스트 + 버튼
    return this._generateFallback(intent.raw);
  }

  _generateCustom(intent) {
    const { keywords } = intent;
    const nodes = [], edges = [];
    let hasContainer = keywords.components.length > 1;
    let container = null;

    if (hasContainer) {
      container = NODE.container(keywords.style);
      nodes.push(container);
    }

    // 데이터 먼저
    let stateNode = null;
    if (keywords.data.includes('state')) {
      stateNode = NODE.state('value', '0');
      nodes.push(stateNode);
    }

    let arrayNode = null;
    if (keywords.data.includes('array')) {
      arrayNode = NODE.array('["항목1","항목2","항목3"]');
      nodes.push(arrayNode);
    }

    // 컴포넌트
    for (const c of keywords.components) {
      let n;
      if (c === 'button') {
        n = NODE.button('확인');
        nodes.push(n);
        // 핸들러 연결
        if (keywords.logic.includes('handler')) {
          const h = NODE.handler('handleClick');
          nodes.push(h);
          edges.push({ from: h.id, fromPort: 0, to: n.id, toPort: 1 });
        }
      } else if (c === 'text') {
        n = NODE.text(keywords.title ?? '텍스트', 'p');
        nodes.push(n);
        if (stateNode) edges.push({ from: stateNode.id, fromPort: 0, to: n.id, toPort: 0 });
      } else if (c === 'input') {
        n = NODE.input('입력하세요');
        nodes.push(n);
      } else if (c === 'card') {
        n = NODE.card(keywords.title ?? '카드');
        nodes.push(n);
      }

      if (container && n) {
        edges.push({ from: n.id, fromPort: 0, to: container.id, toPort: 0 });
      }
    }

    return { nodes, edges, label: intent.raw };
  }

  _generateFallback(raw) {
    const t = NODE.text(raw.slice(0, 20), 'p');
    const b = NODE.button('확인');
    const c = NODE.container();
    return {
      nodes: [c, t, b],
      edges: [
        { from: t.id, fromPort: 0, to: c.id, toPort: 0 },
        { from: b.id, fromPort: 0, to: c.id, toPort: 0 },
      ],
      label: raw,
    };
  }
}

// ─── 템플릿 정의 ──────────────────────────────────────────────────

const TEMPLATES = {
  login: () => {
    const email = NODE.input('이메일', 'email');
    const pw = NODE.input('비밀번호', 'password');
    const btn = NODE.button('로그인', 'primary');
    const handler = NODE.handler('handleLogin');
    const card = NODE.card('로그인');
    return {
      nodes: [card, email, pw, btn, handler],
      edges: [
        { from: email.id, fromPort: 0, to: card.id, toPort: 0 },
        { from: pw.id,    fromPort: 0, to: card.id, toPort: 0 },
        { from: btn.id,   fromPort: 0, to: card.id, toPort: 0 },
        { from: handler.id, fromPort: 0, to: btn.id, toPort: 1 },
      ],
      label: '로그인 폼',
    };
  },

  register: () => {
    const name = NODE.input('이름', 'text');
    const email = NODE.input('이메일', 'email');
    const pw = NODE.input('비밀번호', 'password');
    const pw2 = NODE.input('비밀번호 확인', 'password');
    const btn = NODE.button('회원가입', 'primary');
    const handler = NODE.handler('handleRegister');
    const card = NODE.card('회원가입');
    return {
      nodes: [card, name, email, pw, pw2, btn, handler],
      edges: [
        { from: name.id,  fromPort: 0, to: card.id, toPort: 0 },
        { from: email.id, fromPort: 0, to: card.id, toPort: 0 },
        { from: pw.id,    fromPort: 0, to: card.id, toPort: 0 },
        { from: pw2.id,   fromPort: 0, to: card.id, toPort: 0 },
        { from: btn.id,   fromPort: 0, to: card.id, toPort: 0 },
        { from: handler.id, fromPort: 0, to: btn.id, toPort: 1 },
      ],
      label: '회원가입 폼',
    };
  },

  counter: () => {
    const state = NODE.state('count', '0');
    const display = NODE.text('0', 'h2');
    const incBtn = NODE.button('+1', 'primary');
    const decBtn = NODE.button('-1', 'secondary');
    const resetBtn = NODE.button('초기화', 'ghost');
    const incH = NODE.handler('handleInc');
    const decH = NODE.handler('handleDec');
    const container = NODE.container('row');
    return {
      nodes: [state, display, incBtn, decBtn, resetBtn, incH, decH, container],
      edges: [
        { from: state.id,  fromPort: 0, to: display.id, toPort: 0 },
        { from: incH.id,   fromPort: 0, to: incBtn.id, toPort: 1 },
        { from: decH.id,   fromPort: 0, to: decBtn.id, toPort: 1 },
        { from: incBtn.id, fromPort: 0, to: container.id, toPort: 0 },
        { from: decBtn.id, fromPort: 0, to: container.id, toPort: 0 },
        { from: resetBtn.id, fromPort: 0, to: container.id, toPort: 0 },
      ],
      label: '카운터 앱',
    };
  },

  search: () => {
    const queryState = NODE.state('query', '""');
    const input = NODE.input('검색어 입력...', 'text');
    const btn = NODE.button('검색', 'primary');
    const results = NODE.text('검색 결과', 'p');
    const handler = NODE.handler('handleSearch');
    const container = NODE.container('column');
    const row = NODE.container('row');
    return {
      nodes: [queryState, input, btn, results, handler, container, row],
      edges: [
        { from: queryState.id, fromPort: 0, to: input.id, toPort: 0 },
        { from: handler.id, fromPort: 0, to: btn.id, toPort: 1 },
        { from: input.id,   fromPort: 0, to: row.id, toPort: 0 },
        { from: btn.id,     fromPort: 0, to: row.id, toPort: 0 },
        { from: row.id,     fromPort: 0, to: container.id, toPort: 0 },
        { from: results.id, fromPort: 0, to: container.id, toPort: 0 },
      ],
      label: '검색 UI',
    };
  },

  todo: () => {
    const items = NODE.state('todos', '[]');
    const input = NODE.input('할 일 입력...', 'text');
    const addBtn = NODE.button('추가', 'primary');
    const list = NODE.text('할 일 목록', 'ul');
    const addH = NODE.handler('handleAdd');
    const container = NODE.container('column');
    const row = NODE.container('row');
    return {
      nodes: [items, input, addBtn, list, addH, container, row],
      edges: [
        { from: items.id,  fromPort: 0, to: list.id, toPort: 0 },
        { from: addH.id,   fromPort: 0, to: addBtn.id, toPort: 1 },
        { from: input.id,  fromPort: 0, to: row.id, toPort: 0 },
        { from: addBtn.id, fromPort: 0, to: row.id, toPort: 0 },
        { from: row.id,    fromPort: 0, to: container.id, toPort: 0 },
        { from: list.id,   fromPort: 0, to: container.id, toPort: 0 },
      ],
      label: 'Todo 리스트',
    };
  },

  'profile-card': () => {
    const nameConst = NODE.constant('홍길동', 'string');
    const roleConst = NODE.constant('개발자', 'string');
    const nameText = NODE.text('홍길동', 'h3');
    const roleText = NODE.text('개발자', 'p');
    const followBtn = NODE.button('팔로우', 'primary');
    const msgBtn = NODE.button('메시지', 'secondary');
    const card = NODE.card('프로필');
    const btnRow = NODE.container('row');
    return {
      nodes: [nameConst, roleConst, nameText, roleText, followBtn, msgBtn, card, btnRow],
      edges: [
        { from: nameConst.id, fromPort: 0, to: nameText.id, toPort: 0 },
        { from: roleConst.id, fromPort: 0, to: roleText.id, toPort: 0 },
        { from: followBtn.id, fromPort: 0, to: btnRow.id, toPort: 0 },
        { from: msgBtn.id,    fromPort: 0, to: btnRow.id, toPort: 0 },
        { from: nameText.id,  fromPort: 0, to: card.id, toPort: 0 },
        { from: roleText.id,  fromPort: 0, to: card.id, toPort: 0 },
        { from: btnRow.id,    fromPort: 0, to: card.id, toPort: 0 },
      ],
      label: '프로필 카드',
    };
  },

  'comment-form': () => {
    const authorState = NODE.state('author', '""');
    const commentState = NODE.state('comment', '""');
    const nameInput = NODE.input('작성자 이름', 'text');
    const commentInput = NODE.input('댓글 내용...', 'text');
    const submitBtn = NODE.button('댓글 작성', 'primary');
    const handler = NODE.handler('handleComment');
    const card = NODE.card('댓글 작성');
    return {
      nodes: [authorState, commentState, nameInput, commentInput, submitBtn, handler, card],
      edges: [
        { from: authorState.id,  fromPort: 0, to: nameInput.id, toPort: 0 },
        { from: commentState.id, fromPort: 0, to: commentInput.id, toPort: 0 },
        { from: handler.id,    fromPort: 0, to: submitBtn.id, toPort: 1 },
        { from: nameInput.id,  fromPort: 0, to: card.id, toPort: 0 },
        { from: commentInput.id, fromPort: 0, to: card.id, toPort: 0 },
        { from: submitBtn.id,  fromPort: 0, to: card.id, toPort: 0 },
      ],
      label: '댓글 폼',
    };
  },

  checkout: () => {
    const nameInput = NODE.input('이름', 'text');
    const cardInput = NODE.input('카드 번호', 'text');
    const expiryInput = NODE.input('유효기간 (MM/YY)', 'text');
    const cvvInput = NODE.input('CVV', 'password');
    const payBtn = NODE.button('결제하기', 'primary');
    const cancelBtn = NODE.button('취소', 'ghost');
    const handler = NODE.handler('handlePay');
    const card = NODE.card('결제 정보');
    const btnRow = NODE.container('row');
    return {
      nodes: [nameInput, cardInput, expiryInput, cvvInput, payBtn, cancelBtn, handler, card, btnRow],
      edges: [
        { from: handler.id,    fromPort: 0, to: payBtn.id, toPort: 1 },
        { from: payBtn.id,     fromPort: 0, to: btnRow.id, toPort: 0 },
        { from: cancelBtn.id,  fromPort: 0, to: btnRow.id, toPort: 0 },
        { from: nameInput.id,  fromPort: 0, to: card.id, toPort: 0 },
        { from: cardInput.id,  fromPort: 0, to: card.id, toPort: 0 },
        { from: expiryInput.id, fromPort: 0, to: card.id, toPort: 0 },
        { from: cvvInput.id,   fromPort: 0, to: card.id, toPort: 0 },
        { from: btnRow.id,     fromPort: 0, to: card.id, toPort: 0 },
      ],
      label: '결제 폼',
    };
  },

  settings: () => {
    const themeState = NODE.state('theme', '"light"');
    const notifState = NODE.state('notifications', 'true');
    const langState  = NODE.state('language', '"ko"');
    const themeText  = NODE.text('테마 설정', 'h3');
    const notifText  = NODE.text('알림 설정', 'h3');
    const langText   = NODE.text('언어 설정', 'h3');
    const saveBtn    = NODE.button('저장', 'primary');
    const handler    = NODE.handler('handleSave');
    const container  = NODE.container('column');
    const card       = NODE.card('설정');
    return {
      nodes: [themeState, notifState, langState, themeText, notifText, langText, saveBtn, handler, container, card],
      edges: [
        { from: themeState.id, fromPort: 0, to: themeText.id, toPort: 0 },
        { from: notifState.id, fromPort: 0, to: notifText.id, toPort: 0 },
        { from: langState.id,  fromPort: 0, to: langText.id, toPort: 0 },
        { from: handler.id,    fromPort: 0, to: saveBtn.id, toPort: 1 },
        { from: themeText.id,  fromPort: 0, to: container.id, toPort: 0 },
        { from: notifText.id,  fromPort: 0, to: container.id, toPort: 0 },
        { from: langText.id,   fromPort: 0, to: container.id, toPort: 0 },
        { from: saveBtn.id,    fromPort: 0, to: container.id, toPort: 0 },
        { from: container.id,  fromPort: 0, to: card.id, toPort: 0 },
      ],
      label: '설정 페이지',
    };
  },

  dashboard: () => {
    const stat1 = NODE.constant('1,234', 'string');
    const stat2 = NODE.constant('56%', 'string');
    const stat3 = NODE.constant('789', 'string');
    const c1 = NODE.card('총 사용자');
    const c2 = NODE.card('전환율');
    const c3 = NODE.card('매출');
    const refreshBtn = NODE.button('새로고침', 'secondary');
    const container = NODE.container('row');
    return {
      nodes: [stat1, stat2, stat3, c1, c2, c3, refreshBtn, container],
      edges: [
        { from: stat1.id, fromPort: 0, to: c1.id, toPort: 0 },
        { from: stat2.id, fromPort: 0, to: c2.id, toPort: 0 },
        { from: stat3.id, fromPort: 0, to: c3.id, toPort: 0 },
        { from: c1.id,    fromPort: 0, to: container.id, toPort: 0 },
        { from: c2.id,    fromPort: 0, to: container.id, toPort: 0 },
        { from: c3.id,    fromPort: 0, to: container.id, toPort: 0 },
      ],
      label: '대시보드',
    };
  },

  modal: () => {
    const openState = NODE.state('isOpen', 'false');
    const title = NODE.text('모달 제목', 'h2');
    const content = NODE.text('모달 내용을 여기에 입력하세요.', 'p');
    const confirmBtn = NODE.button('확인', 'primary');
    const cancelBtn = NODE.button('취소', 'ghost');
    const openBtn = NODE.button('모달 열기', 'secondary');
    const openH = NODE.handler('handleOpen');
    const closeH = NODE.handler('handleClose');
    const card = NODE.card('모달');
    const btnRow = NODE.container('row');
    return {
      nodes: [openState, title, content, confirmBtn, cancelBtn, openBtn, openH, closeH, card, btnRow],
      edges: [
        { from: openH.id,   fromPort: 0, to: openBtn.id, toPort: 1 },
        { from: closeH.id,  fromPort: 0, to: confirmBtn.id, toPort: 1 },
        { from: confirmBtn.id, fromPort: 0, to: btnRow.id, toPort: 0 },
        { from: cancelBtn.id,  fromPort: 0, to: btnRow.id, toPort: 0 },
        { from: title.id,   fromPort: 0, to: card.id, toPort: 0 },
        { from: content.id, fromPort: 0, to: card.id, toPort: 0 },
        { from: btnRow.id,  fromPort: 0, to: card.id, toPort: 0 },
      ],
      label: '모달',
    };
  },

  navbar: () => {
    const logo = NODE.text('MyApp', 'h1');
    const homeBtn = NODE.button('홈', 'ghost');
    const aboutBtn = NODE.button('소개', 'ghost');
    const contactBtn = NODE.button('연락처', 'ghost');
    const loginBtn = NODE.button('로그인', 'primary');
    const nav = NODE.container('row');
    return {
      nodes: [logo, homeBtn, aboutBtn, contactBtn, loginBtn, nav],
      edges: [
        { from: logo.id,     fromPort: 0, to: nav.id, toPort: 0 },
        { from: homeBtn.id,  fromPort: 0, to: nav.id, toPort: 0 },
        { from: aboutBtn.id, fromPort: 0, to: nav.id, toPort: 0 },
        { from: contactBtn.id, fromPort: 0, to: nav.id, toPort: 0 },
        { from: loginBtn.id, fromPort: 0, to: nav.id, toPort: 0 },
      ],
      label: '네비게이션 바',
    };
  },

  'single-button': (intent) => {
    const raw = intent?.raw ?? '';
    const label = raw.replace(/(버튼|button)/gi, '').trim() || '버튼';
    const btn = NODE.button(label || '버튼');
    const handler = NODE.handler('handleClick');
    return {
      nodes: [btn, handler],
      edges: [{ from: handler.id, fromPort: 0, to: btn.id, toPort: 1 }],
      label: `버튼: ${label}`,
    };
  },

  'single-card': (intent) => {
    const raw = intent?.raw ?? '';
    const title = raw.replace(/(카드|card)/gi, '').trim() || '카드';
    const card = NODE.card(title || '카드');
    const content = NODE.text('카드 내용', 'p');
    return {
      nodes: [card, content],
      edges: [{ from: content.id, fromPort: 0, to: card.id, toPort: 0 }],
      label: `카드: ${title}`,
    };
  },

  'input-form': () => {
    const input = NODE.input('입력하세요');
    const btn = NODE.button('제출', 'primary');
    const handler = NODE.handler('handleSubmit');
    const container = NODE.container('column');
    return {
      nodes: [input, btn, handler, container],
      edges: [
        { from: handler.id, fromPort: 0, to: btn.id, toPort: 1 },
        { from: input.id,   fromPort: 0, to: container.id, toPort: 0 },
        { from: btn.id,     fromPort: 0, to: container.id, toPort: 0 },
      ],
      label: '입력 폼',
    };
  },
};

// ─── 레이아웃 엔진 ────────────────────────────────────────────────

class LayoutEngine {
  /**
   * 노드 목록 + 엣지 → 위치 자동 계산
   * 레이어 기반 배치: 데이터 → 로직 → 컴포넌트 순
   */
  layout(nodes, edges, offsetX = 100, offsetY = 80) {
    const W = 200, H = 140, GAP_X = 60, GAP_Y = 30;

    const layers = {
      data:      nodes.filter(n => n.type === 'data'),
      logic:     nodes.filter(n => n.type === 'logic'),
      component: nodes.filter(n => n.type === 'component'),
    };

    const result = {};
    let baseX = offsetX;

    for (const [layer, layerNodes] of Object.entries(layers)) {
      if (!layerNodes.length) continue;

      layerNodes.forEach((n, i) => {
        result[n.id] = {
          x: baseX,
          y: offsetY + i * (H + GAP_Y),
        };
      });

      baseX += W + GAP_X;
    }

    return result;
  }

  /**
   * 기존 노드 위치에서 겹치지 않는 위치 찾기
   */
  findFreePosition(existingPositions, nodeCount) {
    const W = 200, H = 140, GAP = 40;
    const cols = Math.ceil(Math.sqrt(nodeCount));
    const positions = [];

    for (let i = 0; i < nodeCount; i++) {
      const col = i % cols;
      const row = Math.floor(i / cols);
      const baseX = 600 + col * (W + GAP);
      const baseY = 80 + row * (H + GAP);
      positions.push({ x: baseX, y: baseY });
    }

    return positions;
  }
}

// ─── 메인 AI 노드 생성기 ─────────────────────────────────────────

class AINodeGenerator {
  constructor() {
    this.parser = new IntentParser();
    this.templates = new TemplateEngine();
    this.layout = new LayoutEngine();

    // LLM 브릿지 (선택적)
    this.llmEndpoint = null;
  }

  /**
   * 텍스트 → 그래프 JSON
   * @param {string} text - 자연어 설명
   * @param {{ offsetX?, offsetY?, existingNodes? }} opts
   * @returns {{ nodes: object, edges: object[], label: string, intent: string }}
   */
  async generate(text, opts = {}) {
    // 1) 의도 파악
    const intent = this.parser.parse(text);

    // 2) LLM 있으면 시도
    if (this.llmEndpoint) {
      try {
        const llmResult = await this._callLLM(text);
        if (llmResult) return this._finalize(llmResult, opts, intent.type);
      } catch { /* LLM 실패 시 규칙 기반으로 폴백 */ }
    }

    // 3) 템플릿/규칙 기반 생성
    const raw = this.templates.generate(intent);

    return this._finalize(raw, opts, intent.type);
  }

  _finalize(raw, opts, intentType) {
    const { offsetX = 100, offsetY = 80 } = opts;

    // 위치 계산
    const positions = this.layout.layout(raw.nodes, raw.edges, offsetX, offsetY);

    // 노드 객체화
    const nodes = {};
    for (const n of raw.nodes) {
      nodes[n.id] = {
        ...n,
        position: positions[n.id] ?? { x: offsetX, y: offsetY },
      };
    }

    // 엣지 ID 부여
    const edges = raw.edges.map((e, i) => ({ id: e.id ?? `ae-${i}`, ...e }));

    return {
      nodes,
      edges,
      label: raw.label,
      intent: intentType,
      nodeCount: raw.nodes.length,
      edgeCount: edges.length,
    };
  }

  /**
   * LLM API 연동 (로컬 서버 or Claude API)
   */
  async _callLLM(text) {
    const SYSTEM = `You are a FreeWire node graph generator.
Given a UI description, return a JSON graph with nodes and edges.
Node types: component (button/text/input/card/container), data (state/const/array), logic (handler/setState/condition).
Return only valid JSON: { "nodes": [...], "edges": [...], "label": "..." }`;

    const res = await fetch(this.llmEndpoint, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ system: SYSTEM, message: text }),
    });

    if (!res.ok) throw new Error('LLM API error');
    const data = await res.json();

    // 응답에서 JSON 추출
    const jsonMatch = (data.content ?? data.text ?? '').match(/\{[\s\S]*\}/);
    if (!jsonMatch) throw new Error('No JSON in LLM response');
    return JSON.parse(jsonMatch[0]);
  }

  /**
   * LLM 서버 설정
   */
  setLLMEndpoint(url) {
    this.llmEndpoint = url;
  }

  /**
   * 지원 의도 목록
   */
  getSupportedIntents() {
    return [
      { intent: 'login', example: '로그인 폼 만들어줘' },
      { intent: 'register', example: '회원가입 폼' },
      { intent: 'counter', example: '카운터 앱' },
      { intent: 'search', example: '검색 UI' },
      { intent: 'todo', example: '할 일 리스트' },
      { intent: 'profile-card', example: '프로필 카드' },
      { intent: 'comment-form', example: '댓글 폼' },
      { intent: 'checkout', example: '결제 폼' },
      { intent: 'settings', example: '설정 페이지' },
      { intent: 'dashboard', example: '대시보드' },
      { intent: 'modal', example: '모달 팝업' },
      { intent: 'navbar', example: '네비게이션 바' },
      { intent: 'single-button', example: '버튼 하나만' },
      { intent: 'single-card', example: '카드 UI' },
      { intent: 'input-form', example: '입력 폼' },
    ];
  }
}

module.exports = { AINodeGenerator, IntentParser, TemplateEngine, LayoutEngine };

