test('검색 UI 패턴 인식', () => {
  const r = parser.parse('검색 기능 추가');
  assertEqual(r.type, 'search', '의도');
});

test('회원가입 패턴 인식', () => {
  const r = parser.parse('회원가입 form');
  assertEqual(r.type, 'register', '의도');
});

test('모달 패턴 인식', () => {
  const r = parser.parse('모달 팝업 만들어');
  assertEqual(r.type, 'modal', '의도');
});

test('키워드 기반 커스텀 생성 (버튼+입력)', () => {
  const r = parser.parse('버튼이랑 입력 필드 필요해');
  assert(['custom', 'single-button', 'input-form'].includes(r.type), `타입 ${r.type}`);
});

test('raw 텍스트 보존', () => {
  const text = '테스트 텍스트';
  const r = parser.parse(text);
  assertEqual(r.raw, text, 'raw');
});

// ──────────────────────────────────────────
// 2. TemplateEngine 테스트
// ──────────────────────────────────────────
console.log('\n📌 TemplateEngine (10개)');

const templates = new TemplateEngine();

test('로그인 템플릿 노드 생성', () => {
  const r = templates.generate({ type: 'login', raw: '로그인' });
  assert(r.nodes.length >= 4, `노드 ${r.nodes.length}개`);
  assert(r.edges.length >= 3, `엣지 ${r.edges.length}개`);
});

test('카운터 템플릿 state 포함', () => {
  const r = templates.generate({ type: 'counter', raw: '카운터' });
  const stateNodes = r.nodes.filter(n => n.type === 'data' && n.subtype === 'state');
  assert(stateNodes.length >= 1, 'state 노드 없음');
});

test('todo 템플릿 state+input+button', () => {
  const r = templates.generate({ type: 'todo', raw: 'todo' });
  const types = r.nodes.map(n => n.subtype);
  assert(types.includes('state'), 'state 없음');
  assert(types.includes('input'), 'input 없음');
  assert(types.includes('button'), 'button 없음');
});

test('대시보드 템플릿 카드 3개', () => {
  const r = templates.generate({ type: 'dashboard', raw: '대시보드' });
  const cards = r.nodes.filter(n => n.subtype === 'card');
  assert(cards.length >= 3, `카드 ${cards.length}개`);
});

test('결제 템플릿 입력 4개 이상', () => {
  const r = templates.generate({ type: 'checkout', raw: '결제' });
  const inputs = r.nodes.filter(n => n.subtype === 'input');
  assert(inputs.length >= 4, `입력 ${inputs.length}개`);
});

test('프로필 카드 템플릿 label 확인', () => {
  const r = templates.generate({ type: 'profile-card', raw: '프로필' });
  assert(r.label.length > 0, 'label 없음');
});

test('네비게이션 바 템플릿 row 컨테이너', () => {
  const r = templates.generate({ type: 'navbar', raw: 'navbar' });
  const containers = r.nodes.filter(n => n.subtype === 'container');
  assert(containers.length >= 1, 'container 없음');
  assert(containers[0].props.direction === 'row', 'row 아님');
});

test('single-button 템플릿', () => {
  const r = templates.generate({ type: 'single-button', raw: '로그아웃 버튼' });
  const btns = r.nodes.filter(n => n.subtype === 'button');
  assert(btns.length >= 1, '버튼 없음');
});

test('알 수 없는 타입 폴백 생성', () => {
  const r = templates.generate({ type: 'unknown-xyz', raw: '알수없는 폼' });
  assert(r.nodes.length >= 1, '노드 없음');
});

test('커스텀 키워드 버튼+입력 생성', () => {
  const intent = {
    type: 'custom',
    keywords: {
      components: ['button', 'input'],
      data: [],
      logic: [],
      style: 'column',
      title: null,
    },
    raw: '버튼이랑 입력',
  };
  const r = templates.generate(intent);
  assert(r.nodes.length >= 2, '노드 부족');
});

// ──────────────────────────────────────────
// 3. LayoutEngine 테스트
// ──────────────────────────────────────────
console.log('\n📌 LayoutEngine (5개)');

const layoutEng = new LayoutEngine();

test('데이터/로직/컴포넌트 레이어 배치', () => {
  const nodes = [
    { id: 'n1', type: 'data' },
    { id: 'n2', type: 'logic' },
    { id: 'n3', type: 'component' },
  ];
  const pos = layoutEng.layout(nodes, []);
  assert(pos['n1'].x < pos['n2'].x, '데이터가 로직보다 오른쪽');
  assert(pos['n2'].x < pos['n3'].x, '로직이 컴포넌트보다 오른쪽');
});

test('같은 레이어 Y 간격 확인', () => {
  const nodes = [
    { id: 'a', type: 'component' },
    { id: 'b', type: 'component' },
  ];
  const pos = layoutEng.layout(nodes, []);
  assert(pos['b'].y > pos['a'].y, 'Y 증가 안 함');
});

test('offsetX/Y 적용', () => {
  const nodes = [{ id: 'x', type: 'data' }];
  const pos = layoutEng.layout(nodes, [], 200, 150);
  assertEqual(pos['x'].x, 200, 'offsetX');
  assertEqual(pos['x'].y, 150, 'offsetY');
});

test('빈 노드 배열 처리', () => {
  const pos = layoutEng.layout([], []);
  assert(typeof pos === 'object', '객체가 아님');
});

test('findFreePosition 위치 목록 생성', () => {
  const positions = layoutEng.findFreePosition({}, 4);
  assert(positions.length === 4, `4개 아님: ${positions.length}`);
  assert(positions[0].x >= 0, 'x < 0');
});

// ──────────────────────────────────────────
// 4. AINodeGenerator 통합 테스트
// ──────────────────────────────────────────
console.log('\n📌 AINodeGenerator 통합 (10개)');

const gen = new AINodeGenerator();

async function testAsync(name, fn) {
  try {
    await fn();
    console.log(`  ✅ ${name}`);
    passed++;
  } catch (e) {
    console.log(`  ❌ ${name}: ${e.message}`);
    failed++;
  }
}

async function runIntegrationTests() {
  await testAsync('로그인 폼 생성 전체 흐름', async () => {
    const r = await gen.generate('로그인 폼 만들어줘');
    assert(typeof r.nodes === 'object', 'nodes 없음');
    assert(r.edges.length > 0, 'edges 없음');
    assertEqual(r.intent, 'login', '의도');
  });

  await testAsync('노드에 position 포함', async () => {
    const r = await gen.generate('카운터');
    for (const n of Object.values(r.nodes)) {
      assert(typeof n.position?.x === 'number', `position.x 없음: ${n.id}`);
      assert(typeof n.position?.y === 'number', `position.y 없음: ${n.id}`);
    }
  });

  await testAsync('엣지에 id 부여', async () => {
    const r = await gen.generate('로그인');
    for (const e of r.edges) {
      assert(e.id, '엣지 id 없음');
    }
  });

  await testAsync('nodeCount/edgeCount 정보 포함', async () => {
    const r = await gen.generate('대시보드');
    assert(typeof r.nodeCount === 'number', 'nodeCount 없음');
    assert(typeof r.edgeCount === 'number', 'edgeCount 없음');
    assert(r.nodeCount > 0, 'nodeCount 0');
  });

  await testAsync('offsetX/Y 옵션 적용', async () => {
    const r = await gen.generate('버튼', { offsetX: 300, offsetY: 200 });
    const positions = Object.values(r.nodes).map(n => n.position);
    assert(positions.some(p => p.x >= 300), 'offsetX 미적용');
  });

  await testAsync('todo 생성 label 확인', async () => {
    const r = await gen.generate('할일 목록 만들어');
    assert(r.label.length > 0, 'label 없음');
  });

  await testAsync('register 생성', async () => {
    const r = await gen.generate('회원가입 폼');
    assertEqual(r.intent, 'register', '의도');
    assert(r.nodeCount >= 5, `노드 부족: ${r.nodeCount}`);
  });

  await testAsync('search UI 생성', async () => {
    const r = await gen.generate('검색 기능');
    assertEqual(r.intent, 'search', '의도');
  });

  await testAsync('setLLMEndpoint 설정', async () => {
    const g = new AINodeGenerator();
    g.setLLMEndpoint('http://localhost:11434/api/generate');
    assert(g.llmEndpoint !== null, 'endpoint 없음');
  });

  await testAsync('getSupportedIntents 15개', () => {
    const intents = gen.getSupportedIntents();
    assert(intents.length >= 15, `${intents.length}개`);
    assert(intents[0].intent && intents[0].example, '구조 오류');
  });

  // 최종 결과
  console.log('\n─────────────────────────────────');
  if (failed === 0) {
    console.log(`✅ 전체 통과: ${passed}/${passed + failed}`);
  } else {
    console.log(`결과: ${passed} 통과 / ${failed} 실패`);
  }
  console.log('─────────────────────────────────\n');

  process.exit(failed > 0 ? 1 : 0);
}

runIntegrationTests();

