function aiParseIntent(text) {
  const t = text.toLowerCase().trim();
  for (const [pat, type] of AI_PATTERNS) {
    if (pat.test(t)) return type;
  }
  return 'generic';
}

function aiLayout(nodes, offsetX=100, offsetY=80) {
  const W=200, H=140, GAP_X=60, GAP_Y=30;
  const layers = { data:[], logic:[], component:[] };
  for (const n of nodes) { (layers[n.type] || layers.component).push(n); }
  const pos = {}; let baseX = offsetX;
  for (const [, layerNodes] of Object.entries(layers)) {
    if (!layerNodes.length) continue;
    layerNodes.forEach((n, i) => { pos[n.id] = { x:baseX, y:offsetY + i*(H+GAP_Y) }; });
    baseX += W + GAP_X;
  }
  return pos;
}

async function aiGenerate(text) {
  const type = aiParseIntent(text);
  const tmpl = AI_TEMPLATES[type];
  const raw = tmpl ? tmpl(text) : AI_TEMPLATES['input-form']();
  const positions = aiLayout(raw.nodes);
  const nodes = {};
  for (const n of raw.nodes) {
    nodes[n.id] = { ...n, position: positions[n.id] ?? { x:100, y:80 } };
  }
  const edges = raw.edges.map((e, i) => ({ id:`ae-${i}`, ...e }));
  return { nodes, edges, label:raw.label, intent:type, nodeCount:raw.nodes.length };
}

