/* ─── 메인 ──────────── */
#editor-container {
  flex: 1;
  overflow: hidden;
}

/* ─── 하단 상태바 ──── */
#statusbar {
  display: flex;
  align-items: center;
  gap: 16px;
  padding: 0 12px;
  height: 24px;
  background: var(--bg2);
  border-top: 1px solid var(--border);
  font-size: 11px;
  color: var(--dim);
  flex-shrink: 0;
}

#statusbar .status-item {
  display: flex;
  align-items: center;
  gap: 4px;
}

/* ─── 시작 템플릿 모달 ─ */
#template-modal {
  position: fixed;
  inset: 0;
  background: rgba(0,0,0,.7);
  display: flex;
  align-items: center;
  justify-content: center;
  z-index: 9999;
}

.modal-card {
  background: var(--bg2);
  border: 1px solid var(--border);
  border-radius: 12px;
  padding: 24px;
  width: 520px;
  max-height: 80vh;
  overflow-y: auto;
}

.modal-card h2 {
  font-size: 16px;
  margin-bottom: 4px;

