// ─── 브라우저 미니 컴파일러 (노드 그래프 → HTML) ───────────────

/**
 * 노드 그래프 → { html, css, js, freelang } 변환
 * FreeExecutor 브라우저 포트. 서버 불필요.
 */
function browserCompile(nodes, wires) {
  const nodesArr = [...nodes.values()].map(v => v.def ?? v);
  const wiresArr = [...wires.values()];

  // 노드 타입 분류
  const stateNodes  = nodesArr.filter(n => n.type === 'data' && n.subtype === 'state');
  const constNodes  = nodesArr.filter(n => n.type === 'data' && n.subtype === 'const');
  const compNodes   = nodesArr.filter(n => n.type === 'component');
  const handlerNodes= nodesArr.filter(n => n.type === 'logic' && n.subtype === 'handler');

  // ── FreeLang 코드 생성 ──────────────────────────
  const freelang = generateFreeLang(nodesArr, wiresArr, stateNodes, constNodes, compNodes, handlerNodes);

  // ── CSS ─────────────────────────────────────────
  const css = generateCSS(compNodes);

  // ── JS ──────────────────────────────────────────
  const js = generateJS(stateNodes, handlerNodes, nodesArr);

  // ── HTML ─────────────────────────────────────────
  const html = generateHTML(compNodes, stateNodes, nodesArr, wiresArr);

  return { html, css, js, freelang };
}

function generateFreeLang(nodesArr, wiresArr, stateNodes, constNodes, compNodes, handlerNodes) {
  const lines = ['component MyApp {'];

  if (stateNodes.length) {
    lines.push('  state {');
    stateNodes.forEach(n => lines.push(`    ${n.props?.name ?? 'value'}: ${n.props?.initial ?? '0'}`));
    lines.push('  }');
  }

  if (compNodes.length) {
    lines.push('  markup {');
    compNodes.forEach(n => {
      const p = n.props ?? {};
      if (n.subtype === 'button')    lines.push(`    button(label: "${p.label ?? '버튼'}", variant: "${p.variant ?? 'primary'}")`);
      else if (n.subtype === 'text') lines.push(`    text(content: "${p.content ?? '텍스트'}", tag: "${p.tag ?? 'p'}")`);
      else if (n.subtype === 'input') lines.push(`    input(placeholder: "${p.placeholder ?? ''}", type: "${p.type ?? 'text'}")`);
      else if (n.subtype === 'card') lines.push(`    card(title: "${p.title ?? '카드'}")`);
      else if (n.subtype === 'container') lines.push(`    container(direction: "${p.direction ?? 'column'}")`);
    });
    lines.push('  }');
  }

  lines.push('}');
  return lines.join('\n');
}

function generateCSS(compNodes) {
  const base = `
* { box-sizing: border-box; margin: 0; padding: 0; }
body { font-family: -apple-system, 'Segoe UI', sans-serif; font-size: 14px;
       background: #f8fafc; color: #1e293b; padding: 20px; }
.fw-app { display: flex; flex-direction: column; gap: 12px; max-width: 480px; margin: 0 auto; }
button { padding: 8px 18px; border-radius: 6px; border: none; cursor: pointer; font-size: 13px; font-weight: 600; transition: opacity .15s; }
button:hover { opacity: .85; }
button.primary { background: #3b82f6; color: #fff; }
button.secondary { background: #64748b; color: #fff; }
button.ghost { background: transparent; border: 1px solid #cbd5e1; color: #475569; }
input { width: 100%; padding: 8px 12px; border: 1px solid #cbd5e1; border-radius: 6px; font-size: 13px; outline: none; }
input:focus { border-color: #3b82f6; box-shadow: 0 0 0 2px rgba(59,130,246,.2); }
.card { background: #fff; border: 1px solid #e2e8f0; border-radius: 10px; padding: 20px;
        box-shadow: 0 1px 4px rgba(0,0,0,.07); display: flex; flex-direction: column; gap: 10px; }
.card-title { font-size: 15px; font-weight: 700; color: #1e293b; margin-bottom: 4px; }
.container-row { display: flex; gap: 10px; align-items: center; flex-wrap: wrap; }
.container-col { display: flex; flex-direction: column; gap: 10px; }
h1,h2,h3 { color: #1e293b; }
h1 { font-size: 22px; } h2 { font-size: 18px; } h3 { font-size: 15px; }
p { color: #475569; line-height: 1.5; }
ul { padding-left: 20px; color: #475569; }
`.trim();
  return base;
}

function generateJS(stateNodes, handlerNodes, nodesArr) {
  if (stateNodes.length === 0 && handlerNodes.length === 0) return '';

  const lines = ['(function() { "use strict";'];

  // state
  stateNodes.forEach(n => {
    const name = n.props?.name ?? 'value';
    const init = n.props?.initial ?? '0';
    lines.push(`  var ${name} = ${isNaN(init) ? JSON.stringify(init.replace(/^"|"$/g,'')) : init};`);
  });

  // _updateDOM
  lines.push('  function _updateDOM() {');
  stateNodes.forEach(n => {
    const name = n.props?.name ?? 'value';
    lines.push(`    document.querySelectorAll('[data-bind="${name}"]').forEach(function(el){ el.textContent = ${name}; });`);
  });
  lines.push('  }');

  // 버튼 이벤트
  const btnNodes = nodesArr.filter(n => n.subtype === 'button');
  btnNodes.forEach((n, i) => {
    const label = n.props?.label ?? '';
    const btnId = `fw-btn-${n.id ?? i}`;
    const stateTarget = stateNodes[0];
    if (stateTarget) {
      const name = stateTarget.props?.name ?? 'value';
      if (/\+/.test(label)) lines.push(`  function _click_${i}(){ ${name}++; _updateDOM(); }`);
      else if (/-/.test(label)) lines.push(`  function _click_${i}(){ ${name}--; _updateDOM(); }`);
      else if (/초기화|reset/i.test(label)) lines.push(`  function _click_${i}(){ ${name} = 0; _updateDOM(); }`);
      else lines.push(`  function _click_${i}(){ _updateDOM(); }`);
    } else {
      lines.push(`  function _click_${i}(){ _updateDOM(); }`);
    }
  });

  lines.push('  document.addEventListener("DOMContentLoaded", function() {');
  btnNodes.forEach((n, i) => {
    lines.push(`    var b${i}=document.querySelector('[data-fw-id="${n.id ?? i}"]');`);
    lines.push(`    if(b${i}) b${i}.addEventListener("click", _click_${i});`);
  });
  lines.push('    _updateDOM();');
  lines.push('  });');
  lines.push('})();');
  return lines.join('\n');
}

function generateHTML(compNodes, stateNodes, nodesArr, wiresArr) {
  // 위상 정렬: 컨테이너/카드가 자식 먼저 삽입되는 순서
  const parts = [];

  // 카드/컨테이너 감지
  const containers = compNodes.filter(n => n.subtype === 'card' || n.subtype === 'container');
  const inContainer = new Set();

  // 컨테이너에 연결된 자식 수집
  const childrenOf = {};
  for (const c of containers) {
    childrenOf[c.id] = [];
  }
  for (const w of wiresArr) {
    const srcDef = nodesArr.find(n => n.id === (w.fn ?? w.from));
    const dstDef = nodesArr.find(n => n.id === (w.tn ?? w.to));
    if (srcDef && dstDef && childrenOf[dstDef.id] !== undefined) {
      childrenOf[dstDef.id].push(srcDef);
      inContainer.add(srcDef.id);
    }
  }

  function nodeToHTML(n) {
    const p = n.props ?? {};
    const id = n.id ?? '';
    if (n.subtype === 'button') {
      const cls = p.variant ?? 'primary';
      const stateTarget = stateNodes[0];
      const bindAttr = stateTarget ? ` data-bind="${stateTarget.props?.name}"` : '';
      return `<button class="${cls}" data-fw-id="${id}">${p.label ?? '버튼'}</button>`;
    }
    if (n.subtype === 'text') {
      const tag = p.tag ?? 'p';
      const stateName = stateNodes[0]?.props?.name;
      const hasState = stateNodes.some(s => {
        return wiresArr.some(w => (w.fn ?? w.from) === s.id && (w.tn ?? w.to) === n.id);
      });
      const content = hasState && stateName
        ? `<span data-bind="${stateName}">${stateNodes[0]?.props?.initial ?? '0'}</span>`
        : (p.content ?? '텍스트');
      return `<${tag}>${content}</${tag}>`;
    }
    if (n.subtype === 'input') {
      return `<input type="${p.type ?? 'text'}" placeholder="${p.placeholder ?? ''}" />`;
    }
    if (n.subtype === 'card') {
      const children = (childrenOf[id] ?? []).map(nodeToHTML).join('\n      ');
      return `<div class="card">\n      <div class="card-title">${p.title ?? '카드'}</div>\n      ${children}\n    </div>`;
    }
    if (n.subtype === 'container') {
      const dir = p.direction === 'row' ? 'row' : 'col';
      const children = (childrenOf[id] ?? []).map(nodeToHTML).join('\n      ');
      return `<div class="container-${dir}">\n      ${children}\n    </div>`;
    }
    return '';
  }

  // 최상위 노드만 렌더링 (컨테이너에 속하지 않은 것)
  for (const n of compNodes) {
    if (!inContainer.has(n.id)) {
      const html = nodeToHTML(n);
      if (html) parts.push('    ' + html);
    }
  }

  // 노드가 없으면 플레이스홀더
  if (parts.length === 0) {
    return '<div class="fw-app"><p style="color:#94a3b8;text-align:center">노드를 추가하고 ▶ 실행을 누르세요</p></div>';
  }

  return `<div class="fw-app">\n${parts.join('\n')}\n  </div>`;
}

function buildPreviewDocument(html, css, js) {
  return `<!DOCTYPE html>
<html lang="ko">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>FreeWire Preview</title>
<style>${css}</style>
</head>
<body>
${html}
${js ? `<script>${js}<\/script>` : ''}
</body>
</html>`;
}

