/**
 * FreeWire Phase 6 - 브라우저 Live Preview 테스트
 * 브라우저 미니 컴파일러를 Node.js에서 시뮬레이션
 * 실행: node src/test/test-phase6.js
 */

'use strict';

let passed = 0, failed = 0;

function test(name, fn) {
  try {
    fn();
    console.log(`  ✅ ${name}`);
    passed++;
  } catch (e) {
    console.log(`  ❌ ${name}: ${e.message}`);
    failed++;
  }
}

function assert(cond, msg) {
  if (!cond) throw new Error(msg ?? 'assertion failed');
}

// ──────────────────────────────────────────
// 브라우저 미니 컴파일러 (Node.js 포트)
// ──────────────────────────────────────────

function mockNodes(defs) {
  const map = new Map();
  defs.forEach(d => map.set(d.id, { def: d, ...d }));
  return map;
}

function mockWires(arr) {
  const map = new Map();
  arr.forEach((w, i) => map.set(`w${i}`, { fn: w.from, fp: w.fromPort ?? 0, tn: w.to, tp: w.toPort ?? 0 }));
  return map;
}

// 미니 컴파일러 로직 (www/index.html에서 포팅)
function generateFreeLang(nodesArr) {
  const stateNodes = nodesArr.filter(n => n.type === 'data' && n.subtype === 'state');
  const compNodes  = nodesArr.filter(n => n.type === 'component');
  const lines = ['component MyApp {'];
  if (stateNodes.length) {
    lines.push('  state {');
    stateNodes.forEach(n => lines.push(`    ${n.props?.name ?? 'value'}: ${n.props?.initial ?? '0'}`));
    lines.push('  }');
  }
  if (compNodes.length) {
    lines.push('  markup {');
    compNodes.forEach(n => {
      const p = n.props ?? {};
      if (n.subtype === 'button')    lines.push(`    button(label: "${p.label ?? '버튼'}", variant: "${p.variant ?? 'primary'}")`);
      else if (n.subtype === 'text') lines.push(`    text(content: "${p.content ?? '텍스트'}", tag: "${p.tag ?? 'p'}")`);
      else if (n.subtype === 'input') lines.push(`    input(placeholder: "${p.placeholder ?? ''}", type: "${p.type ?? 'text'}")`);
      else if (n.subtype === 'card') lines.push(`    card(title: "${p.title ?? '카드'}")`);
      else if (n.subtype === 'container') lines.push(`    container(direction: "${p.direction ?? 'column'}")`);
    });
    lines.push('  }');
  }
  lines.push('}');
  return lines.join('\n');
}

function generateJS(stateNodes, nodesArr) {
  if (stateNodes.length === 0) return '';
  const lines = ['(function() { "use strict";'];
  stateNodes.forEach(n => {
    const name = n.props?.name ?? 'value';
    const init = n.props?.initial ?? '0';
    lines.push(`  var ${name} = ${isNaN(init) ? JSON.stringify(init.replace(/^"|"$/g,'')) : init};`);
  });
  lines.push('})();');
  return lines.join('\n');
}

function generateHTML(compNodes, stateNodes, nodesArr, wiresArr) {
  const parts = [];
  const containers = compNodes.filter(n => n.subtype === 'card' || n.subtype === 'container');
  const inContainer = new Set();
  const childrenOf = {};
  for (const c of containers) childrenOf[c.id] = [];
  for (const w of wiresArr) {
    const srcDef = nodesArr.find(n => n.id === w.fn);
    const dstDef = nodesArr.find(n => n.id === w.tn);
    if (srcDef && dstDef && childrenOf[dstDef.id] !== undefined) {
      childrenOf[dstDef.id].push(srcDef);
      inContainer.add(srcDef.id);
    }
  }
  function nodeToHTML(n) {
    const p = n.props ?? {};
    if (n.subtype === 'button') return `<button class="${p.variant ?? 'primary'}" data-fw-id="${n.id}">${p.label ?? '버튼'}</button>`;
    if (n.subtype === 'text')  { const tag = p.tag ?? 'p'; return `<${tag}>${p.content ?? '텍스트'}</${tag}>`; }
    if (n.subtype === 'input') return `<input type="${p.type ?? 'text'}" placeholder="${p.placeholder ?? ''}" />`;
    if (n.subtype === 'card')  {
      const ch = (childrenOf[n.id] ?? []).map(nodeToHTML).join('');
      return `<div class="card"><div class="card-title">${p.title ?? '카드'}</div>${ch}</div>`;
    }
    if (n.subtype === 'container') {
      const dir = p.direction === 'row' ? 'row' : 'col';
      const ch = (childrenOf[n.id] ?? []).map(nodeToHTML).join('');
      return `<div class="container-${dir}">${ch}</div>`;
    }
    return '';
  }
  for (const n of compNodes) {
    if (!inContainer.has(n.id)) {
      const h = nodeToHTML(n);
      if (h) parts.push(h);
    }
  }
  return parts.length === 0 ? '<div class="fw-app"></div>' : `<div class="fw-app">${parts.join('')}</div>`;
}

function browserCompileTest(nodes, wires) {
  const nodesArr = [...nodes.values()].map(v => v.def ?? v);
  const wiresArr = [...wires.values()];
  const stateNodes  = nodesArr.filter(n => n.type === 'data' && n.subtype === 'state');
  const compNodes   = nodesArr.filter(n => n.type === 'component');
  const freelang = generateFreeLang(nodesArr);
  const css = '/* css */';
  const js = generateJS(stateNodes, nodesArr);
  const html = generateHTML(compNodes, stateNodes, nodesArr, wiresArr);
  return { html, css, js, freelang };
}

// ──────────────────────────────────────────
// 1. FreeLang 코드 생성 테스트
// ──────────────────────────────────────────
console.log('\n📌 FreeLang 코드 생성 (8개)');

test('버튼 노드 → FreeLang button 구문', () => {
  const nodes = mockNodes([{ id:'b1', type:'component', subtype:'button', props:{label:'+1',variant:'primary'} }]);
  const r = browserCompileTest(nodes, new Map());
  assert(r.freelang.includes('button(label: "+1"'), `actual: ${r.freelang}`);
});

test('상태 노드 → state 블록 포함', () => {
  const nodes = mockNodes([{ id:'s1', type:'data', subtype:'state', props:{name:'count',initial:'0'} }]);
  const r = browserCompileTest(nodes, new Map());
  assert(r.freelang.includes('state {'), `state 없음`);
  assert(r.freelang.includes('count: 0'), `count 없음`);
});

test('텍스트 노드 → text 구문', () => {
  const nodes = mockNodes([{ id:'t1', type:'component', subtype:'text', props:{content:'안녕',tag:'h2'} }]);
  const r = browserCompileTest(nodes, new Map());
  assert(r.freelang.includes('text(content: "안녕"'), `actual: ${r.freelang}`);
});

test('입력 노드 → input 구문', () => {
  const nodes = mockNodes([{ id:'i1', type:'component', subtype:'input', props:{placeholder:'이메일',type:'email'} }]);
  const r = browserCompileTest(nodes, new Map());
  assert(r.freelang.includes('input(placeholder: "이메일"'), `actual: ${r.freelang}`);
});

test('카드 노드 → card 구문', () => {
  const nodes = mockNodes([{ id:'c1', type:'component', subtype:'card', props:{title:'로그인'} }]);
  const r = browserCompileTest(nodes, new Map());
  assert(r.freelang.includes('card(title: "로그인"'), `actual: ${r.freelang}`);
});

test('component MyApp { } 래퍼', () => {
  const nodes = mockNodes([{ id:'b1', type:'component', subtype:'button', props:{label:'확인'} }]);
  const r = browserCompileTest(nodes, new Map());
  assert(r.freelang.startsWith('component MyApp {'), '래퍼 없음');
  assert(r.freelang.trim().endsWith('}'), '닫는 괄호 없음');
});

test('빈 그래프 → 빈 markup', () => {
  const r = browserCompileTest(new Map(), new Map());
  assert(r.freelang.includes('component MyApp {'), '래퍼 없음');
  assert(!r.freelang.includes('markup {'), '빈 markup 있으면 안됨');
});

test('컨테이너 노드 → container 구문', () => {
  const nodes = mockNodes([{ id:'cn1', type:'component', subtype:'container', props:{direction:'row'} }]);
  const r = browserCompileTest(nodes, new Map());
  assert(r.freelang.includes('container(direction: "row"'), `actual: ${r.freelang}`);
});

// ──────────────────────────────────────────
// 2. HTML 생성 테스트
// ──────────────────────────────────────────
console.log('\n📌 HTML 생성 (8개)');

test('버튼 → <button> 태그', () => {
  const nodes = mockNodes([{ id:'b1', type:'component', subtype:'button', props:{label:'클릭',variant:'primary'} }]);
  const r = browserCompileTest(nodes, new Map());
  assert(r.html.includes('<button'), `button 없음: ${r.html}`);
  assert(r.html.includes('클릭'), `label 없음`);
});

test('텍스트(h2) → <h2> 태그', () => {
  const nodes = mockNodes([{ id:'t1', type:'component', subtype:'text', props:{content:'제목',tag:'h2'} }]);
  const r = browserCompileTest(nodes, new Map());
  assert(r.html.includes('<h2>제목</h2>'), `actual: ${r.html}`);
});

test('입력 → <input> 태그', () => {
  const nodes = mockNodes([{ id:'i1', type:'component', subtype:'input', props:{placeholder:'검색...',type:'text'} }]);
  const r = browserCompileTest(nodes, new Map());
  assert(r.html.includes('<input'), `input 없음`);
  assert(r.html.includes('검색...'), `placeholder 없음`);
});

test('카드 → .card 클래스 + card-title', () => {
  const nodes = mockNodes([{ id:'c1', type:'component', subtype:'card', props:{title:'프로필'} }]);
  const r = browserCompileTest(nodes, new Map());
  assert(r.html.includes('class="card"'), `class 없음: ${r.html}`);
  assert(r.html.includes('프로필'), `title 없음`);
});

test('컨테이너(row) → .container-row', () => {
  const nodes = mockNodes([{ id:'cn1', type:'component', subtype:'container', props:{direction:'row'} }]);
  const r = browserCompileTest(nodes, new Map());
  assert(r.html.includes('container-row'), `row 없음: ${r.html}`);
});

test('와이어로 연결된 자식 카드 내부 배치', () => {
  const nodes = mockNodes([
    { id:'c1', type:'component', subtype:'card',   props:{title:'카드'} },
    { id:'b1', type:'component', subtype:'button', props:{label:'확인'} },
  ]);
  const wires = mockWires([{ from:'b1', to:'c1', fromPort:0, toPort:0 }]);
  const r = browserCompileTest(nodes, wires);
  // 버튼이 카드 내부에 있어야 함
  const cardIdx = r.html.indexOf('class="card"');
  const btnIdx  = r.html.indexOf('<button');
  assert(cardIdx < btnIdx, `버튼이 카드 밖에 있음: ${r.html}`);
});

test('fw-app 래퍼 포함', () => {
  const nodes = mockNodes([{ id:'t1', type:'component', subtype:'text', props:{content:'hi',tag:'p'} }]);
  const r = browserCompileTest(nodes, new Map());
  assert(r.html.includes('fw-app'), `fw-app 없음`);
});

test('상태 연결 시 data-bind 속성', () => {
  const nodes = mockNodes([
    { id:'s1', type:'data',      subtype:'state', props:{name:'count',initial:'0'} },
    { id:'t1', type:'component', subtype:'text',  props:{content:'0',tag:'h2'} },
  ]);
  const wires = mockWires([{ from:'s1', to:'t1', fromPort:0, toPort:0 }]);
  const r = browserCompileTest(nodes, wires);
  assert(r.html.includes('data-bind="count"'), `data-bind 없음: ${r.html}`);
});

// ──────────────────────────────────────────
// 3. JS 생성 테스트
// ──────────────────────────────────────────
console.log('\n📌 JS 생성 (5개)');

test('상태 노드 있으면 JS 생성', () => {
  const nodes = mockNodes([{ id:'s1', type:'data', subtype:'state', props:{name:'count',initial:'0'} }]);
  const r = browserCompileTest(nodes, new Map());
  assert(r.js.includes('var count'), `var count 없음: ${r.js}`);
});

test('상태 없으면 빈 JS', () => {
  const nodes = mockNodes([{ id:'b1', type:'component', subtype:'button', props:{label:'확인'} }]);
  const r = browserCompileTest(nodes, new Map());
  assert(r.js === '' || !r.js.includes('var '), `불필요한 JS: ${r.js}`);
});

test('숫자 초기값 정수로', () => {
  const nodes = mockNodes([{ id:'s1', type:'data', subtype:'state', props:{name:'n',initial:'42'} }]);
  const r = browserCompileTest(nodes, new Map());
  assert(r.js.includes('var n = 42'), `actual: ${r.js}`);
});

test('IIFE 래퍼', () => {
  const nodes = mockNodes([{ id:'s1', type:'data', subtype:'state', props:{name:'x',initial:'0'} }]);
  const r = browserCompileTest(nodes, new Map());
  assert(r.js.includes('(function()'), `IIFE 없음`);
});

test('여러 상태 모두 포함', () => {
  const nodes = mockNodes([
    { id:'s1', type:'data', subtype:'state', props:{name:'a',initial:'1'} },
    { id:'s2', type:'data', subtype:'state', props:{name:'b',initial:'2'} },
  ]);
  const r = browserCompileTest(nodes, new Map());
  assert(r.js.includes('var a'), `a 없음`);
  assert(r.js.includes('var b'), `b 없음`);
});

// ──────────────────────────────────────────
// 4. 통합 케이스
// ──────────────────────────────────────────
console.log('\n📌 통합 케이스 (4개)');

test('카운터 전체 컴파일', () => {
  const nodes = mockNodes([
    { id:'s1', type:'data',      subtype:'state',   props:{name:'count',initial:'0'} },
    { id:'t1', type:'component', subtype:'text',    props:{content:'0',tag:'h2'} },
    { id:'b1', type:'component', subtype:'button',  props:{label:'+1',variant:'primary'} },
    { id:'b2', type:'component', subtype:'button',  props:{label:'-1',variant:'secondary'} },
  ]);
  const wires = mockWires([{ from:'s1', to:'t1', fromPort:0, toPort:0 }]);
  const r = browserCompileTest(nodes, wires);
  assert(r.freelang.includes('count: 0'), 'state 없음');
  assert(r.html.includes('<button'), 'button 없음');
  assert(r.html.includes('data-bind="count"'), 'data-bind 없음');
  assert(r.js.includes('var count'), 'JS 없음');
});

test('로그인 폼 전체 컴파일', () => {
  const nodes = mockNodes([
    { id:'i1', type:'component', subtype:'input',  props:{placeholder:'이메일',type:'email'} },
    { id:'i2', type:'component', subtype:'input',  props:{placeholder:'비밀번호',type:'password'} },
    { id:'b1', type:'component', subtype:'button', props:{label:'로그인',variant:'primary'} },
    { id:'c1', type:'component', subtype:'card',   props:{title:'로그인'} },
  ]);
  const wires = mockWires([
    { from:'i1', to:'c1' }, { from:'i2', to:'c1' }, { from:'b1', to:'c1' }
  ]);
  const r = browserCompileTest(nodes, wires);
  assert(r.html.includes('이메일'), '이메일 없음');
  assert(r.html.includes('로그인'), '로그인 없음');
  assert(r.html.includes('class="card"'), 'card 없음');
});

test('빈 그래프 플레이스홀더', () => {
  const r = browserCompileTest(new Map(), new Map());
  assert(typeof r.html === 'string', 'html 없음');
  assert(typeof r.css === 'string',  'css 없음');
  assert(typeof r.freelang === 'string', 'freelang 없음');
});

test('반환 객체 구조 검증', () => {
  const nodes = mockNodes([{ id:'b1', type:'component', subtype:'button', props:{label:'확인'} }]);
  const r = browserCompileTest(nodes, new Map());
  assert('html' in r, 'html 없음');
  assert('css' in r, 'css 없음');
  assert('js' in r, 'js 없음');
  assert('freelang' in r, 'freelang 없음');
});

// ──────────────────────────────────────────
// 결과
// ──────────────────────────────────────────
console.log('\n─────────────────────────────────');
if (failed === 0) {
  console.log(`✅ 전체 통과: ${passed}/${passed + failed}`);
} else {
  console.log(`결과: ${passed} 통과 / ${failed} 실패`);
}
console.log('─────────────────────────────────\n');
process.exit(failed > 0 ? 1 : 0);

