// ──────────────────────────────────────────
// 브라우저 미니 컴파일러 (Node.js 포트)
// ──────────────────────────────────────────

function mockNodes(defs) {
  const map = new Map();
  defs.forEach(d => map.set(d.id, { def: d, ...d }));
  return map;
}

function mockWires(arr) {
  const map = new Map();
  arr.forEach((w, i) => map.set(`w${i}`, { fn: w.from, fp: w.fromPort ?? 0, tn: w.to, tp: w.toPort ?? 0 }));
  return map;
}

// 미니 컴파일러 로직 (www/index.html에서 포팅)
function generateFreeLang(nodesArr) {
  const stateNodes = nodesArr.filter(n => n.type === 'data' && n.subtype === 'state');
  const compNodes  = nodesArr.filter(n => n.type === 'component');
  const lines = ['component MyApp {'];
  if (stateNodes.length) {
    lines.push('  state {');
    stateNodes.forEach(n => lines.push(`    ${n.props?.name ?? 'value'}: ${n.props?.initial ?? '0'}`));
    lines.push('  }');
  }
  if (compNodes.length) {
    lines.push('  markup {');
    compNodes.forEach(n => {
      const p = n.props ?? {};
      if (n.subtype === 'button')    lines.push(`    button(label: "${p.label ?? '버튼'}", variant: "${p.variant ?? 'primary'}")`);
      else if (n.subtype === 'text') lines.push(`    text(content: "${p.content ?? '텍스트'}", tag: "${p.tag ?? 'p'}")`);
      else if (n.subtype === 'input') lines.push(`    input(placeholder: "${p.placeholder ?? ''}", type: "${p.type ?? 'text'}")`);
      else if (n.subtype === 'card') lines.push(`    card(title: "${p.title ?? '카드'}")`);
      else if (n.subtype === 'container') lines.push(`    container(direction: "${p.direction ?? 'column'}")`);
    });
    lines.push('  }');
  }
  lines.push('}');
  return lines.join('\n');
}

function generateJS(stateNodes, nodesArr) {
  if (stateNodes.length === 0) return '';
  const lines = ['(function() { "use strict";'];
  stateNodes.forEach(n => {
    const name = n.props?.name ?? 'value';
    const init = n.props?.initial ?? '0';
    lines.push(`  var ${name} = ${isNaN(init) ? JSON.stringify(init.replace(/^"|"$/g,'')) : init};`);
  });
  lines.push('})();');
  return lines.join('\n');
}

function generateHTML(compNodes, stateNodes, nodesArr, wiresArr) {
  const parts = [];
  const containers = compNodes.filter(n => n.subtype === 'card' || n.subtype === 'container');
  const inContainer = new Set();
  const childrenOf = {};
  for (const c of containers) childrenOf[c.id] = [];
  for (const w of wiresArr) {
    const srcDef = nodesArr.find(n => n.id === w.fn);
    const dstDef = nodesArr.find(n => n.id === w.tn);
    if (srcDef && dstDef && childrenOf[dstDef.id] !== undefined) {
      childrenOf[dstDef.id].push(srcDef);
      inContainer.add(srcDef.id);
    }
  }
  function nodeToHTML(n) {
    const p = n.props ?? {};
    if (n.subtype === 'button') return `<button class="${p.variant ?? 'primary'}" data-fw-id="${n.id}">${p.label ?? '버튼'}</button>`;
    if (n.subtype === 'text')  { const tag = p.tag ?? 'p'; return `<${tag}>${p.content ?? '텍스트'}</${tag}>`; }
    if (n.subtype === 'input') return `<input type="${p.type ?? 'text'}" placeholder="${p.placeholder ?? ''}" />`;
    if (n.subtype === 'card')  {
      const ch = (childrenOf[n.id] ?? []).map(nodeToHTML).join('');
      return `<div class="card"><div class="card-title">${p.title ?? '카드'}</div>${ch}</div>`;
    }
    if (n.subtype === 'container') {
      const dir = p.direction === 'row' ? 'row' : 'col';
      const ch = (childrenOf[n.id] ?? []).map(nodeToHTML).join('');
      return `<div class="container-${dir}">${ch}</div>`;
    }
    return '';
  }
  for (const n of compNodes) {
    if (!inContainer.has(n.id)) {
      const h = nodeToHTML(n);
      if (h) parts.push(h);
    }
  }
  return parts.length === 0 ? '<div class="fw-app"></div>' : `<div class="fw-app">${parts.join('')}</div>`;
}

function browserCompileTest(nodes, wires) {
  const nodesArr = [...nodes.values()].map(v => v.def ?? v);
  const wiresArr = [...wires.values()];
  const stateNodes  = nodesArr.filter(n => n.type === 'data' && n.subtype === 'state');
  const compNodes   = nodesArr.filter(n => n.type === 'component');
  const freelang = generateFreeLang(nodesArr);
  const css = '/* css */';
  const js = generateJS(stateNodes, nodesArr);
  const html = generateHTML(compNodes, stateNodes, nodesArr, wiresArr);
  return { html, css, js, freelang };
}

