    (c.warns||[]).forEach(w => {
      if (!inputFacts.has(w)) violations.push({ type:'warning', fact:w, msg:`"${w}" 권장`, severity:'warning', nodeLabel:n.label??n.subtype, repairHint:`enhance_${w}` });
    });
    (c.produces||[]).concat(c.ensures||[]).forEach(f=>satisfied.add(f));
  }

  // 버튼↔핸들러 체크
  const buttons  = nodesArr.filter(n=>n.subtype==='button');
  const handlers = nodesArr.filter(n=>n.subtype==='handler');
  if (buttons.length > 0 && handlers.length === 0) {
    violations.push({ type:'structural', fact:'action.handler.present', msg:`버튼 ${buttons.length}개에 핸들러 없음 — 클릭이 동작하지 않습니다`, severity:'error', nodeLabel:'그래프', repairHint:'add_handler_node' });
  }
  for (const b of buttons) {
    const connected = wiresArr.some(w=>(w.tn??w.to)===b.id&&(w.tp??w.toPort)===1);
    if (!connected && handlers.length > 0) {
      violations.push({ type:'structural', fact:'ui.button.connected', msg:`버튼 "${b.props?.label??b.id}"에 핸들러 미연결`, severity:'error', nodeLabel:b.label??'버튼', repairHint:'wire_handler_to_button', nodeId:b.id });
    }
  }

  // state↔text 바인딩 체크
  const stateNodes = nodesArr.filter(n=>n.subtype==='state');
  const textNodes  = nodesArr.filter(n=>n.subtype==='text');
  for (const st of stateNodes) {
    const hasOut = wiresArr.some(w=>(w.fn??w.from)===st.id);
    if (!hasOut && textNodes.length > 0) {
      violations.push({ type:'structural', fact:'state.bound', msg:`상태 "${st.props?.name??st.id}"가 UI에 바인딩 안 됨`, severity:'warning', nodeLabel:st.label??'상태', repairHint:'wire_state_to_display', nodeId:st.id });
    } else if (hasOut) satisfied.add('state.bound');
  }

  return buildIntentReport(violations, satisfied, goal);
}

function buildIntentReport(violations, satisfied, goal) {
  const errors   = violations.filter(v=>v.severity==='error');
  const warnings = violations.filter(v=>v.severity==='warning');
  const goalFacts = intentParseGoal(goal);
  const satisfiedGoals = goalFacts.filter(f=>satisfied.has(f));
  const score = goalFacts.length > 0
    ? Math.round((satisfiedGoals.length / goalFacts.length) * 100)
    : (errors.length === 0 ? 100 : 20);
  return { score, passed: errors.length===0, errors, warnings, violations, satisfiedFacts:[...satisfied], missingFacts: goalFacts.filter(f=>!satisfied.has(f)) };
}

function intentAutoRepair(nodes, wires, violations, nextId) {
  const nodesArr = [...nodes.values()].map(v=>v.def??v);
  const applied = [];

  for (const v of violations) {
    if (v.repairHint === 'add_handler_node') {
      const btn = nodesArr.find(n=>n.subtype==='button');
      if (!btn) continue;
      const handlerName = /로그인|login/i.test(btn.props?.label) ? 'handleLogin' : /\+/.test(btn.props?.label) ? 'handleIncrement' : 'handleClick';
      const nid = nextId();
      const newNode = {
        id:nid, type:'logic', subtype:'handler', label:`핸들러[${handlerName}]`,
        inputs:[{name:'action',portType:'logic'}], outputs:[{name:'handler',portType:'logic'}],
        props:{name:handlerName}, position:{x:(btn.position?.x??300)+230, y:(btn.position?.y??100)},
      };
      nodes.set(nid, newNode);
      const wid = nextId();
      wires.set(wid, {id:wid, fn:nid, fp:0, tn:btn.id, tp:1});
      applied.push(`핸들러 "${handlerName}" 추가 + 버튼 연결`);
    }

    else if (v.repairHint === 'wire_handler_to_button') {
      const handlerNode = nodesArr.find(n=>n.subtype==='handler');
      if (!handlerNode || !v.nodeId) continue;
      const alreadyWired = [...wires.values()].some(w=>w.fn===handlerNode.id && w.tn===v.nodeId && w.tp===1);
      if (!alreadyWired) {
        const wid = nextId();
        wires.set(wid, {id:wid, fn:handlerNode.id, fp:0, tn:v.nodeId, tp:1});
        applied.push(`핸들러 → 버튼 연결`);
      }
    }

    else if (v.repairHint === 'wire_state_to_display') {
      const stateNode = nodesArr.find(n=>n.id===v.nodeId || n.subtype==='state');
      const textNode  = nodesArr.find(n=>n.subtype==='text');
      if (!stateNode || !textNode) continue;
      const alreadyWired = [...wires.values()].some(w=>w.fn===stateNode.id && w.tn===textNode.id);
      if (!alreadyWired) {
        const wid = nextId();
        wires.set(wid, {id:wid, fn:stateNode.id, fp:0, tn:textNode.id, tp:0});
        applied.push(`상태 → 텍스트 바인딩`);
      }
    }
  }

  return applied;
}

function intentGetNodeViewId(nodes, nodeId) {
  // NodeView Map에서 해당 def.id를 가진 뷰 찾기
  for (const [vid, view] of nodes) {
    if ((view.def?.id ?? view.id) === nodeId) return vid;
  }
  return nodeId;
}

// ─── 브라우저 미니 컴파일러 (노드 그래프 → HTML) ───────────────

