/**
 * FreeWire Phase 8 — Repair History
 *
 * 시스템이 실수를 기억한다.
 *
 * 매 수정마다 이력을 저장하고,
 * "이 노드 조합에서 이 위반이 n번 발생했다"는 패턴을 축적한다.
 *
 * 이 기억이 두 가지에 쓰인다:
 *   1. PatternAdvisor — 다음 그래프 생성 전 사전 경고
 *   2. AdaptiveWeights — 패치 신뢰도 보정 (자주 통한 패치 우선)
 */

'use strict';

// ─── 이력 항목 ───────────────────────────────────────────────

class RepairRecord {
  constructor({ sessionId, timestamp, violation, patch, resultScore, improved }) {
    this.sessionId   = sessionId;
    this.timestamp   = timestamp ?? Date.now();
    this.violation   = violation;   // { type, fact, repairHint, nodeSubtype }
    this.patch       = patch;       // { type, description, confidence }
    this.resultScore = resultScore; // 패치 적용 후 점수
    this.improved    = improved;    // 점수가 올랐나?
  }
}

// ─── RepairHistory ──────────────────────────────────────────

class RepairHistory {
  constructor(maxRecords = 500) {
    this._records   = [];      // RepairRecord[]
    this._maxRecords = maxRecords;

    // 패턴 인덱스: "subtype:fact" → { count, improvedCount, lastSeen }
    this._patternIndex = new Map();

    // 패치 효능 인덱스: "patchType:repairHint" → { applied, improved }
    this._efficacyIndex = new Map();
  }

  // ─── 기록 ──────────────────────────────────────────────

  record(sessionId, violation, patch, resultScore, previousScore) {
    const improved = resultScore > previousScore;

    const rec = new RepairRecord({
      sessionId,
      violation: {
        type:        violation.type,
        fact:        violation.fact,
        repairHint:  violation.repairHint,
        nodeSubtype: violation.nodeSubtype ?? null,
      },
      patch: patch ? {
        type:        patch.type,
        description: patch.description,
        confidence:  patch.confidence,
      } : null,
      resultScore,
      improved,
    });

    this._records.push(rec);
    if (this._records.length > this._maxRecords) {
      this._records.shift(); // 오래된 기록 제거
    }

    this._updatePatternIndex(rec);
    this._updateEfficacyIndex(rec);

    return rec;
  }

  // ─── 패턴 조회 ─────────────────────────────────────────

  /**
   * 특정 (subtype, fact) 조합이 과거에 몇 번 위반됐는지
   */
  patternCount(nodeSubtype, fact) {
    const key = `${nodeSubtype ?? '*'}:${fact}`;
    return this._patternIndex.get(key)?.count ?? 0;
  }

  /**
   * 가장 자주 발생하는 위반 패턴 top N
   */
  topViolations(n = 5) {
    return [...this._patternIndex.entries()]
      .map(([key, v]) => ({ pattern: key, ...v }))
      .sort((a, b) => b.count - a.count)
      .slice(0, n);
  }

  /**
   * 특정 repairHint에 대한 패치 효능 (0-1)
   * 적용 횟수 대비 개선 횟수
   */
  patchEfficacy(patchType, repairHint) {
    const key = `${patchType}:${repairHint}`;
    const e = this._efficacyIndex.get(key);
    if (!e || e.applied === 0) return 0.5; // 기본값
    return e.improved / e.applied;
  }

  /**
   * 과거 이력에서 이 위반을 가장 잘 고쳤던 패치 타입
   */
  bestPatchFor(repairHint) {
    let best = null, bestScore = -1;

    for (const [key, e] of this._efficacyIndex.entries()) {
      if (!key.endsWith(`:${repairHint}`)) continue;
      const score = e.applied > 0 ? e.improved / e.applied : 0;
      if (score > bestScore) {
        bestScore = score;
        best = { patchType: key.split(':')[0], efficacy: score, applied: e.applied };
      }
    }

    return best;
  }

  /**
   * 세션별 이력 요약
   */
  sessionSummary(sessionId) {
    const recs = this._records.filter(r => r.sessionId === sessionId);
    if (recs.length === 0) return null;

    return {
      sessionId,
      totalPatches: recs.length,
      improved:     recs.filter(r => r.improved).length,
      finalScore:   recs[recs.length - 1]?.resultScore ?? 0,
      violations:   [...new Set(recs.map(r => r.violation.fact))],
    };
  }

  /**
   * 전체 통계
   */
  stats() {
    const total    = this._records.length;
    const improved = this._records.filter(r => r.improved).length;
    return {
      totalRecords:   total,
      improvedCount:  improved,
      successRate:    total > 0 ? Math.round((improved / total) * 100) : 0,
      uniquePatterns: this._patternIndex.size,
      topViolations:  this.topViolations(3),
    };
  }

  /**
   * 직렬화 (저장/복원용)
   */
  toJSON() {
    return {
      records:      this._records,
      patternIndex: [...this._patternIndex.entries()],
      efficacyIndex:[...this._efficacyIndex.entries()],
    };
  }

  static fromJSON(json) {
    const h = new RepairHistory();
    h._records       = json.records.map(r => Object.assign(new RepairRecord(r), r));
    h._patternIndex  = new Map(json.patternIndex);
    h._efficacyIndex = new Map(json.efficacyIndex);
    return h;
  }

  // ─── 내부 인덱스 갱신 ──────────────────────────────────

  _updatePatternIndex(rec) {
    const key = `${rec.violation.nodeSubtype ?? '*'}:${rec.violation.fact}`;
    const prev = this._patternIndex.get(key) ?? { count: 0, improvedCount: 0, lastSeen: 0 };
    this._patternIndex.set(key, {
      count:        prev.count + 1,
      improvedCount:prev.improvedCount + (rec.improved ? 1 : 0),
      lastSeen:     rec.timestamp,
    });
  }

  _updateEfficacyIndex(rec) {
    if (!rec.patch) return;
    const key = `${rec.patch.type}:${rec.violation.repairHint}`;
    const prev = this._efficacyIndex.get(key) ?? { applied: 0, improved: 0 };
    this._efficacyIndex.set(key, {
      applied: prev.applied + 1,
      improved: prev.improved + (rec.improved ? 1 : 0),
    });
  }
}

module.exports = { RepairHistory, RepairRecord };

