/**
 * FreeWire Phase 8-10 Tests
 * RepairHistory + PatternAdvisor + ContractInferrer + AdaptiveLoop
 *
 * 총 50개 테스트
 */

'use strict';

const { RepairHistory }    = require('../intent/repair-history');
const { PatternAdvisor }   = require('../intent/pattern-advisor');
const { ContractInferrer, mergeInferredContract } = require('../intent/contract-inferrer');
const {
  AdaptiveLoop,
  createAdaptiveLoop,
  resetGlobalHistory,
  getGlobalHistory,
  defaultNextId,
} = require('../intent/adaptive-loop');

// ─── 테스트 유틸 ─────────────────────────────────────────────

let passed = 0, failed = 0;

function test(name, fn) {
  try {
    fn();
    console.log(`  ✓ ${name}`);
    passed++;
  } catch (e) {
    console.error(`  ✗ ${name}`);
    console.error(`    → ${e.message}`);
    failed++;
  }
}

function assert(condition, msg = 'assertion failed') {
  if (!condition) throw new Error(msg);
}

function assertEqual(a, b, msg) {
  if (a !== b) throw new Error(msg ?? `expected ${JSON.stringify(b)}, got ${JSON.stringify(a)}`);
}

function assertIn(arr, val, msg) {
  if (!arr.includes(val)) throw new Error(msg ?? `${JSON.stringify(val)} not in ${JSON.stringify(arr)}`);
}

// ─── 노드/와이어 팩토리 ──────────────────────────────────────

function makeNode(id, subtype, props = {}, contract = null) {
  const def = {
    id, type: 'component', subtype,
    label: `${subtype}[${id}]`,
    inputs:  [{ name: 'in',  portType: 'data' }],
    outputs: [{ name: 'out', portType: 'data' }],
    props,
    position: { x: 100, y: 100 },
    ...(contract ? { contract } : {}),
  };
  return [id, def];
}

function makeNodes(...defs) {
  const m = new Map();
  for (const [id, def] of defs) m.set(id, def);
  return m;
}

function makeWires(...entries) {
  const m = new Map();
  for (const [id, fn, tn, fp = 0, tp = 0] of entries) {
    m.set(id, { id, fn, fp, tn, tp });
  }
  return m;
}

// ═══════════════════════════════════════════════════════════════
// Phase 8: RepairHistory
// ═══════════════════════════════════════════════════════════════

console.log('\n[Phase 8] RepairHistory');

test('기본 record 저장', () => {
  const h = new RepairHistory();
  h.record('s1',
    { type: 'structural', fact: 'ui.button.connected', repairHint: 'wire_handler_to_button', nodeSubtype: 'button' },
    { type: 'add_wire', description: '연결', confidence: 0.9 },
    80, 60
  );
  assertEqual(h.stats().totalRecords, 1);
});

test('improved 플래그 계산', () => {
  const h = new RepairHistory();
  h.record('s1',
    { fact: 'ui.button.connected', repairHint: 'wire_handler_to_button', nodeSubtype: 'button' },
    { type: 'add_wire', description: '연결', confidence: 0.9 },
    80, 60  // 60→80: improved
  );
  h.record('s1',
    { fact: 'state.bound', repairHint: 'wire_state_to_display', nodeSubtype: 'state' },
    { type: 'add_wire', description: '바인딩', confidence: 0.8 },
    70, 80  // 80→70: not improved
  );
  const stats = h.stats();
  assertEqual(stats.improvedCount, 1);
  assertEqual(stats.successRate, 50);
});

test('patternCount 집계', () => {
  const h = new RepairHistory();
  for (let i = 0; i < 5; i++) {
    h.record(`s${i}`,
      { fact: 'ui.button.connected', repairHint: 'wire_handler_to_button', nodeSubtype: 'button' },
      { type: 'add_wire', description: '연결', confidence: 0.9 },
      80, 60
    );
  }
  assertEqual(h.patternCount('button', 'ui.button.connected'), 5);
});

test('topViolations 정렬', () => {
  const h = new RepairHistory();
  // button 위반 3번
  for (let i = 0; i < 3; i++) h.record(`s${i}`,
    { fact: 'ui.button.connected', repairHint: 'w', nodeSubtype: 'button' },
    null, 50, 50
  );
  // state 위반 5번
  for (let i = 0; i < 5; i++) h.record(`s${i}`,
    { fact: 'state.bound', repairHint: 'w', nodeSubtype: 'state' },
    null, 50, 50
  );
  const top = h.topViolations(1);
  assert(top[0].pattern.includes('state'), 'state가 1위여야');
  assertEqual(top[0].count, 5);
});

test('patchEfficacy 계산', () => {
  const h = new RepairHistory();
  // 3번 적용, 2번 성공
  h.record('s1', { fact: 'f', repairHint: 'wire_handler_to_button', nodeSubtype: 'button' },
    { type: 'add_wire', description: '연결', confidence: 0.9 }, 80, 60); // improved
  h.record('s2', { fact: 'f', repairHint: 'wire_handler_to_button', nodeSubtype: 'button' },
    { type: 'add_wire', description: '연결', confidence: 0.9 }, 70, 60); // improved
  h.record('s3', { fact: 'f', repairHint: 'wire_handler_to_button', nodeSubtype: 'button' },
    { type: 'add_wire', description: '연결', confidence: 0.9 }, 50, 60); // not improved
  const e = h.patchEfficacy('add_wire', 'wire_handler_to_button');
  assert(Math.abs(e - 2/3) < 0.01, `efficacy should be ~0.67, got ${e}`);
});

test('bestPatchFor 조회', () => {
  const h = new RepairHistory();
  h.record('s1', { fact: 'f', repairHint: 'add_handler_node', nodeSubtype: 'button' },
    { type: 'add_node', description: '핸들러 추가', confidence: 0.85 }, 90, 60);
  h.record('s2', { fact: 'f', repairHint: 'add_handler_node', nodeSubtype: 'button' },
    { type: 'add_node', description: '핸들러 추가', confidence: 0.85 }, 85, 60);
  const best = h.bestPatchFor('add_handler_node');
  assert(best !== null, 'bestPatch found');
  assertEqual(best.patchType, 'add_node');
});

test('sessionSummary 집계', () => {
  const h = new RepairHistory();
  h.record('mySession', { fact: 'f1', repairHint: 'r', nodeSubtype: 'button' },
    { type: 'add_wire', description: 'test', confidence: 0.9 }, 80, 60);
  h.record('mySession', { fact: 'f2', repairHint: 'r', nodeSubtype: 'state' },
    { type: 'add_wire', description: 'test', confidence: 0.8 }, 90, 80);
  const s = h.sessionSummary('mySession');
  assertEqual(s.totalPatches, 2);
  assertEqual(s.improved, 2);
});

test('maxRecords 제한', () => {
  const h = new RepairHistory(5);
  for (let i = 0; i < 10; i++) {
    h.record(`s${i}`, { fact: 'f', repairHint: 'r', nodeSubtype: null },
      null, 50, 50);
  }
  assert(h._records.length <= 5, 'maxRecords 초과하면 안 됨');
});

test('toJSON/fromJSON 직렬화', () => {
  const h = new RepairHistory();
  h.record('s1', { fact: 'ui.button.connected', repairHint: 'wire_handler_to_button', nodeSubtype: 'button' },
    { type: 'add_wire', description: '연결', confidence: 0.9 }, 80, 60);
  const json = h.toJSON();
  const h2 = RepairHistory.fromJSON(json);
  assertEqual(h2.stats().totalRecords, 1);
  assertEqual(h2.patternCount('button', 'ui.button.connected'), 1);
});

// ═══════════════════════════════════════════════════════════════
// Phase 8: PatternAdvisor
// ═══════════════════════════════════════════════════════════════

console.log('\n[Phase 8] PatternAdvisor');

test('빈 이력에서 조언 없음', () => {
  const h = new RepairHistory();
  const advisor = new PatternAdvisor(h);
  const nodes = [{ id: 'b1', subtype: 'button', props: {} }];
  const advices = advisor.advise(nodes);
  assertEqual(advices.length, 0, '이력 없으면 조언 없음');
});

test('버튼+핸들러 누락 패턴 경고', () => {
  const h = new RepairHistory();
  // 버튼:핸들러 누락 3번 기록
  for (let i = 0; i < 3; i++) {
    h.record(`s${i}`,
      { fact: 'ui.button.connected', repairHint: 'wire_handler_to_button', nodeSubtype: 'button' },
      null, 50, 50
    );
  }
  const advisor = new PatternAdvisor(h);
  // 버튼은 있고 핸들러는 없는 그래프
  const nodes = [{ id: 'b1', subtype: 'button', props: {} }];
  const advices = advisor.advise(nodes);
  assert(advices.length > 0, '경고가 있어야 함');
  assert(advices[0].occurrences >= 3, '발생 횟수 반영');
});

test('패치 신뢰도 보정 (충분한 이력)', () => {
  const h = new RepairHistory();
  // 5번 적용, 4번 성공 → efficacy = 0.8
  for (let i = 0; i < 5; i++) {
    h.record(`s${i}`,
      { fact: 'ui.button.connected', repairHint: 'add_handler_node', nodeSubtype: 'button' },
      { type: 'add_node', description: '핸들러 추가', confidence: 0.85 },
      i < 4 ? 80 : 50, 60  // 4번 개선
    );
  }
  const advisor = new PatternAdvisor(h);
  const patch = { type: 'add_node', description: '핸들러 추가', confidence: 0.5 };
  const [adjusted] = advisor.adjustConfidence([patch]);
  // efficacy(0.8) * 0.6 + confidence(0.5) * 0.4 = 0.68
  assert(adjusted.confidence > 0.5, '이력 기반 상향 보정');
});

test('패치 신뢰도 보정 (부족한 이력 - 유지)', () => {
  const h = new RepairHistory();
  // 2번만 기록 (3번 미만 → 보정 안 함)
  for (let i = 0; i < 2; i++) {
    h.record(`s${i}`,
      { fact: 'f', repairHint: 'r', nodeSubtype: null },
      { type: 'add_node', description: '테스트', confidence: 0.85 },
      80, 60
    );
  }
  const advisor = new PatternAdvisor(h);
  const patch = { type: 'add_node', description: '테스트', confidence: 0.7 };
  const [adjusted] = advisor.adjustConfidence([patch]);
  assertEqual(adjusted.confidence, 0.7, '이력 부족 시 원래 confidence 유지');
});

test('suggestMissingNodes — 버튼 있으면 핸들러 제안', () => {
  const h = new RepairHistory();
  h.record('s1', { fact: 'ui.button.connected', repairHint: 'w', nodeSubtype: 'handler' },
    null, 50, 50);
  const advisor = new PatternAdvisor(h);
  const nodes = [{ id: 'b1', subtype: 'button', props: {} }];
  const suggestions = advisor.suggestMissingNodes(nodes);
  assert(suggestions.some(s => s.subtype === 'handler'), '핸들러 제안');
});

test('isRepeatedMistake 판별', () => {
  const h = new RepairHistory();
  h.record('s1', { fact: 'state.bound', repairHint: 'w', nodeSubtype: 'state' }, null, 50, 50);
  h.record('s2', { fact: 'state.bound', repairHint: 'w', nodeSubtype: 'state' }, null, 50, 50);
  const advisor = new PatternAdvisor(h);
  assert(advisor.isRepeatedMistake('state.bound', 'state'), '반복 실수 감지');
  assert(!advisor.isRepeatedMistake('unknown.fact', 'button'), '처음 실수는 반복 아님');
});

test('learningReport 생성', () => {
  const h = new RepairHistory();
  h.record('s1', { fact: 'ui.button.connected', repairHint: 'w', nodeSubtype: 'button' },
    { type: 'add_wire', description: 'test', confidence: 0.9 }, 80, 60);
  const advisor = new PatternAdvisor(h);
  const report = advisor.learningReport();
  assert(report.includes('학습 리포트'), '리포트 헤더');
  assert(report.includes('총 수정 이력'), '총 이력');
});

// ═══════════════════════════════════════════════════════════════
// Phase 9: ContractInferrer
// ═══════════════════════════════════════════════════════════════

console.log('\n[Phase 9] ContractInferrer');

test('버튼 노드 — 로그인 label → auth.initiated 추론', () => {
  const inferrer = new ContractInferrer();
  const node = { id: 'b1', subtype: 'button', props: { label: '로그인' }, contract: null };
  const result = inferrer.infer(node);
  assertIn(result.produces, 'auth.initiated', 'auth.initiated 추론');
});

test('버튼 노드 — 제출 label → form.submitted 추론', () => {
  const inferrer = new ContractInferrer();
  const node = { id: 'b1', subtype: 'button', props: { label: '제출하기' } };
  const result = inferrer.infer(node);
  assertIn(result.produces, 'form.submitted');
});

test('input 노드 — email type → form.email.filled 추론', () => {
  const inferrer = new ContractInferrer();
  const node = { id: 'i1', subtype: 'input', props: { type: 'email', placeholder: '이메일' } };
  const result = inferrer.infer(node);
  assertIn(result.produces, 'form.email.filled');
});

test('state 노드 — count name → counter.state.available 추론', () => {
  const inferrer = new ContractInferrer();
  const node = { id: 's1', subtype: 'state', props: { name: 'count', initial: 0 } };
  const result = inferrer.infer(node);
  assertIn(result.produces, 'counter.state.available');
  assertIn(result.produces, 'state.available');
});

test('handler 노드 — requires action.triggered 추론', () => {
  const inferrer = new ContractInferrer();
  const node = { id: 'h1', subtype: 'handler', props: { name: 'handleLogin' } };
  const result = inferrer.infer(node);
  assertIn(result.requires, 'action.triggered');
  assertIn(result.ensures, 'auth.handler.ready');
});

test('text 노드 — state.bound warns 추론', () => {
  const inferrer = new ContractInferrer();
  const node = { id: 't1', subtype: 'text', props: { content: '카운트:' } };
  const result = inferrer.infer(node);
  assertIn(result.warns, 'state.bound');
});

test('goal text 기반 facts 추론', () => {
  const inferrer = new ContractInferrer();
  const node = { id: 'b1', subtype: 'button', props: { label: '클릭' } };
  const result = inferrer.infer(node, [], [], '로그인 폼 만들어줘');
  assertIn(result.produces, 'auth.initiated');
  assertIn(result.sources, 'goal_text');
});

test('구조 기반 추론 — 핸들러가 버튼 소스 → ui.button.connected 추론', () => {
  const inferrer = new ContractInferrer();
  const btnNode = { id: 'b1', subtype: 'button', props: {} };
  const hdlNode = { id: 'h1', subtype: 'handler', props: {} };
  const wires   = [{ fn: 'b1', tn: 'h1', fp: 0, tp: 0 }];
  const result  = inferrer.infer(hdlNode, [btnNode, hdlNode], wires);
  // handler가 button으로부터 wire 받음 → ui.button.connected
  assertIn(result.produces, 'ui.button.connected');
});

test('inferAll — contract 없는 노드에만 적용', () => {
  const inferrer = new ContractInferrer();
  const nodes = makeNodes(
    makeNode('b1', 'button', { label: '로그인' }),
    ['n2', {
      id: 'n2', type: 'component', subtype: 'input',
      props: { type: 'email' },
      contract: { requires: ['x'], ensures: [], produces: ['existing.fact'], warns: [] },
    }]
  );
  const result = inferrer.inferAll(nodes, new Map());
  assert(result.has('b1'), 'contract 없는 버튼 추론');
  assert(!result.has('n2'), '이미 contract 있는 노드는 건드리지 않음');
});

test('mergeInferredContract — 기존 contract 보존', () => {
  const node = {
    id: 'b1', subtype: 'button', props: {},
    contract: { requires: ['x'], ensures: [], produces: ['my.fact'], warns: [] },
  };
  const inferred = { requires: ['y'], ensures: [], produces: ['inferred.fact'], warns: [], sources: [] };
  const merged = mergeInferredContract(node, inferred);
  assertIn(merged.contract.produces, 'my.fact', '기존 fact 보존');
  assert(!merged.contract.produces.includes('inferred.fact'), '추론 fact 덮어쓰지 않음');
});

test('mergeInferredContract — 빈 contract에 추론 주입', () => {
  const node = {
    id: 'b1', subtype: 'button', props: { label: '로그인' },
    contract: { requires: [], ensures: [], produces: [], warns: [] },
  };
  const inferrer = new ContractInferrer();
  const inferred = inferrer.infer(node);
  const merged = mergeInferredContract(node, inferred);
  assertIn(merged.contract.produces, 'auth.initiated', '추론 주입');
  assert(merged.contract._inferred, '_inferred 마킹');
});

test('추론 confidence 계산', () => {
  const inferrer = new ContractInferrer();
  // subtype template + props 분석 + goal text → 높은 confidence
  const node = { id: 'b1', subtype: 'button', props: { label: '로그인' } };
  const result = inferrer.infer(node, [], [], '로그인 폼 만들어줘');
  assert(result.confidence > 0.5, `confidence > 0.5, got ${result.confidence}`);
  assert(result.sources.length > 1, '여러 소스에서 추론');
});

// ═══════════════════════════════════════════════════════════════
// Phase 10: AdaptiveLoop
// ═══════════════════════════════════════════════════════════════

console.log('\n[Phase 10] AdaptiveLoop');

// 테스트 전 전역 이력 초기화
resetGlobalHistory();

test('기본 실행 — 빈 그래프', () => {
  resetGlobalHistory();
  const loop = createAdaptiveLoop({ maxIterations: 2 });
  const result = loop.run('로그인 폼', new Map(), new Map());
  assert(result.finalScore >= 0, '점수 계산');
  assert(Array.isArray(result.trace), 'trace 반환');
  assert(typeof result.learningSummary === 'string', 'learningSummary');
});

test('Contract 자동 추론 카운트', () => {
  resetGlobalHistory();
  const nodes = makeNodes(
    makeNode('b1', 'button', { label: '로그인' }),
    makeNode('i1', 'input', { type: 'email' })
  );
  const loop = createAdaptiveLoop({ maxIterations: 1 });
  const result = loop.run('로그인 폼 만들어줘', nodes, new Map());
  assert(result.inferredContracts >= 0, 'inferredContracts 카운트');
});

test('사전 경고 생성 (이력 있을 때)', () => {
  resetGlobalHistory();
  const h = getGlobalHistory();
  // 이력에 버튼 관련 위반 3번 기록
  for (let i = 0; i < 3; i++) {
    h.record(`pre${i}`,
      { fact: 'ui.button.connected', repairHint: 'wire_handler_to_button', nodeSubtype: 'button' },
      null, 50, 50
    );
  }

  const nodes = makeNodes(makeNode('b1', 'button', { label: '클릭' }));
  const loop = createAdaptiveLoop({ maxIterations: 1 });
  const result = loop.run('버튼 클릭', nodes, new Map());
  // preAdvice는 배열
  assert(Array.isArray(result.preAdvice), 'preAdvice 배열');
});

test('루프가 개선 추적', () => {
  resetGlobalHistory();
  // 버튼 있고 핸들러 없는 그래프 → 자동 수정되면 score 올라감
  const nodes = makeNodes(
    makeNode('b1', 'button', { label: '로그인' }, {
      requires: [], ensures: ['ui.button.clickable'], produces: ['ui.button.clickable'],
      warns: ['ui.button.connected'],
    })
  );
  const loop = createAdaptiveLoop({ maxIterations: 3 });
  const result = loop.run('로그인', nodes, new Map(), defaultNextId());
  assert(result.iterations >= 1, '최소 1회 반복');
  assert(typeof result.converged === 'boolean', 'converged 반환');
});

test('이력이 누적되고 stats가 반영', () => {
  resetGlobalHistory();
  const loop1 = createAdaptiveLoop({ maxIterations: 2 });
  const nodes1 = makeNodes(makeNode('b1', 'button', { label: '로그인' }));
  loop1.run('로그인', nodes1, new Map(), defaultNextId());

  const stats = getGlobalHistory().stats();
  // 실행 후 이력 존재 여부
  assert(typeof stats.totalRecords === 'number', 'totalRecords 존재');
  assert(typeof stats.successRate === 'number', 'successRate 존재');
});

test('같은 세션 ID 재사용 금지 확인', () => {
  resetGlobalHistory();
  const loop = new AdaptiveLoop({ sessionId: 'fixed-session', maxIterations: 1 });
  const nodes = makeNodes(makeNode('b1', 'button', { label: '클릭' }));
  const result = loop.run('클릭', nodes, new Map(), defaultNextId());
  assertEqual(result.sessionId, 'fixed-session', 'sessionId 보존');
});

test('historyStats 반환', () => {
  resetGlobalHistory();
  const loop = createAdaptiveLoop({ maxIterations: 1 });
  const result = loop.run('테스트', new Map(), new Map());
  assert(typeof result.historyStats === 'object', 'historyStats 객체');
  assert(typeof result.historyStats.totalRecords === 'number', 'totalRecords');
  assert(typeof result.historyStats.successRate === 'number', 'successRate');
});

test('전체 파이프라인 — 카운터 앱', () => {
  resetGlobalHistory();
  // 상태 + 버튼들 + 텍스트가 있는 카운터 앱
  const nodes = makeNodes(
    makeNode('state1', 'state', { name: 'count', initial: 0 }),
    makeNode('btn_inc', 'button', { label: '+1 증가' }),
    makeNode('btn_dec', 'button', { label: '-1 감소' }),
    makeNode('txt1', 'text', { content: '카운트:' })
  );
  const loop = createAdaptiveLoop({ maxIterations: 4 });
  const result = loop.run('카운터 앱 만들어줘', nodes, new Map(), defaultNextId());
  assert(result.finalScore >= 0, '점수 계산');
  assert(typeof result.improved === 'boolean', 'improved 반환');
  assert(typeof result.learningSummary === 'string', 'learning summary');
});

test('전체 파이프라인 — 로그인 폼', () => {
  resetGlobalHistory();
  const nodes = makeNodes(
    makeNode('email', 'input', { type: 'email', placeholder: '이메일' }),
    makeNode('pw', 'input', { type: 'password', placeholder: '비밀번호' }),
    makeNode('btn', 'button', { label: '로그인' })
  );
  const loop = createAdaptiveLoop({ maxIterations: 4 });
  const result = loop.run('로그인 폼 만들어줘', nodes, new Map(), defaultNextId());
  assert(result.trace.length >= 1, '최소 1 iteration');
  assert(Array.isArray(result.preAdvice), 'preAdvice 존재');
});

test('학습 리포트 출력', () => {
  resetGlobalHistory();
  const h = getGlobalHistory();
  h.record('s1', { fact: 'ui.button.connected', repairHint: 'w', nodeSubtype: 'button' },
    { type: 'add_wire', description: '연결', confidence: 0.9 }, 80, 60);

  const loop = createAdaptiveLoop();
  const report = loop.learningReport();
  assert(report.includes('학습 리포트'), '리포트 포함');
  assert(report.includes('총 수정 이력'), '이력 통계 포함');
});

// ─── 집계 ────────────────────────────────────────────────────

console.log(`\n결과: ${passed} passed, ${failed} failed / ${passed + failed} total`);
if (failed > 0) process.exit(1);

