// 전역 단축키
document.addEventListener('keydown', e => {
  if (e.key === 'Delete' && editor.selectedNode) editor._removeNode(editor.selectedNode);
  if (e.ctrlKey && e.key === 'f') { e.preventDefault(); editor._fitView(); }
});

// ─── Intent 패널 ──────────────────────────────────────────────

const intentPanel  = document.getElementById('intent-panel');
const intentBody   = document.getElementById('intent-body');
const intentBadge  = document.getElementById('intent-score-badge');
const intentToggle = document.getElementById('intent-toggle');

function runIntentEval(goal) {
  const aiInput2 = document.getElementById('ai-input');
  const goalText = goal ?? (aiInput2 ? aiInput2.value.trim() : '');
  const report   = intentEvaluate(editor.nodes, editor.wires, goalText);

  // 배지 업데이트
  intentBadge.textContent = `${report.score}%`;
  intentBadge.className = 'ip-score ' + (report.score >= 85 ? 'good' : report.score >= 50 ? 'ok' : 'bad');
  intentToggle.className = 'btn-intent' + (report.errors.length > 0 ? ' has-errors' : '');

  // 본문 렌더링
  const parts = [];

  if (report.violations.length === 0) {
    parts.push('<div style="color:var(--green);font-size:12px;padding:8px 0">✅ 모든 계약 충족 — 의도와 일치합니다</div>');
  } else {
    for (const v of report.violations) {
      const icon = v.severity === 'error' ? '❌' : '⚠️';
      const color = v.severity === 'error' ? 'var(--red)' : 'var(--yellow)';
      parts.push(`
        <div class="intent-violation">
          <span class="iv-icon">${icon}</span>
          <div>
            <div class="iv-msg" style="color:${color}">${v.msg}</div>
            <div class="iv-node">${v.nodeLabel}</div>
            <span class="iv-fact">${v.fact}</span>
          </div>
        </div>`);
    }
  }

  // Facts 요약
  if (goalText && report.missingFacts.length > 0) {
    parts.push('<div style="margin-top:8px;font-size:11px;color:var(--dim)">미달성 목표:</div>');
    parts.push('<div>' + report.missingFacts.map(f => `<span class="intent-fact-chip missing">${f}</span>`).join('') + '</div>');
  }
  if (report.satisfiedFacts.length > 0) {
    parts.push('<div style="margin-top:6px;font-size:11px;color:var(--dim)">충족된 Facts:</div>');
    parts.push('<div>' + report.satisfiedFacts.map(f => `<span class="intent-fact-chip">${f}</span>`).join('') + '</div>');
  }

  intentBody.innerHTML = parts.join('');
  return report;
}

intentToggle.addEventListener('click', () => {
  intentPanel.classList.toggle('open');
  if (intentPanel.classList.contains('open')) runIntentEval();
});

document.getElementById('intent-close-btn').addEventListener('click', () => {
  intentPanel.classList.remove('open');
});

// 자동 수정 버튼
document.getElementById('intent-fix-btn').addEventListener('click', () => {
  const aiInput2 = document.getElementById('ai-input');
  const goalText = aiInput2 ? aiInput2.value.trim() : '';
  const report = intentEvaluate(editor.nodes, editor.wires, goalText);

  let nid_ctr = editor.nodeIdCtr;
  const nextId = () => `n${nid_ctr++}`;

  const patches = intentAutoRepair(editor.nodes, editor.wires, report.violations, nextId);
  editor.nodeIdCtr = nid_ctr;

  if (patches.length > 0) {
    // NodeView 재구성 (새로 추가된 raw 노드들을 NodeView로 변환)
    for (const [nid, nodeDef] of editor.nodes) {
      if (!nodeDef.el) {  // NodeView가 아닌 raw def
        const view = new NodeView(nid, nodeDef, nodeDef.position?.x ?? 400, nodeDef.position?.y ?? 200, editor);
        editor.canvas.appendChild(view.el);
        editor.nodes.set(nid, view);
      }
    }
    editor._redrawAll();
    editor._updateCounts();

    // 결과 표시
    const msg = patches.join(', ');
    editor._msg(`⚡ 자동 수정: ${msg}`, 'info');
    runIntentEval(goalText);
  } else {
    editor._msg('수정할 내용이 없습니다', 'warn');
  }
});

// ─── Live Preview 패널 ────────────────────────────────────────

const previewPanel = document.getElementById('preview-panel');
const previewFrame = document.getElementById('preview-frame');
const codeView     = document.getElementById('code-view');
const previewToggle= document.getElementById('preview-toggle');

function runPreview() {
  const { html, css, js, freelang } = browserCompile(editor.nodes, editor.wires);
  const doc = buildPreviewDocument(html, css, js);

  // iframe에 렌더링
  previewFrame.srcdoc = doc;

  // 코드 뷰 (FreeLang)
  codeView.textContent = freelang;

  previewToggle.classList.remove('running');
}

