/* ─── Intent 패널 ────── */
#intent-panel {
  position: fixed;
  bottom: 24px;
  left: 180px;
  right: 20px;
  max-height: 280px;
  background: var(--bg2);
  border: 1px solid var(--border);
  border-radius: 10px;
  box-shadow: 0 -4px 24px rgba(0,0,0,.5);
  z-index: 300;
  display: none;
  flex-direction: column;
  overflow: hidden;
}
#intent-panel.open { display: flex; }

#intent-panel .ip-header {
  display: flex; align-items: center; gap: 8px;
  padding: 8px 14px;
  border-bottom: 1px solid var(--border);
  flex-shrink: 0;
}
#intent-panel .ip-title { font-size: 12px; font-weight: 700; flex: 1; }

.ip-score {
  padding: 2px 10px;
  border-radius: 10px;
  font-size: 11px;
  font-weight: 700;
}
.ip-score.good    { background: rgba(63,185,80,.2);  color: var(--green);  }
.ip-score.ok      { background: rgba(210,153,34,.2); color: var(--yellow); }
.ip-score.bad     { background: rgba(248,81,73,.2);  color: var(--red);    }

.ip-btn {
  padding: 3px 10px;
  border-radius: 5px;
  font-size: 11px;
  font-weight: 600;
  cursor: pointer;
  border: none;
}
.ip-btn-fix   { background: var(--accent); color: #0d1117; }
.ip-btn-close { background: var(--bg3); color: var(--dim); border: 1px solid var(--border); }

#intent-body { overflow-y: auto; padding: 8px 14px; flex: 1; }

.intent-violation {
  display: flex; align-items: flex-start; gap: 8px;
  padding: 5px 0;
  border-bottom: 1px solid rgba(255,255,255,.04);
  font-size: 11px;
}
.iv-icon { font-size: 13px; flex-shrink: 0; margin-top: 1px; }
.iv-msg  { flex: 1; line-height: 1.4; }
.iv-node { font-size: 10px; color: var(--dim); margin-top: 2px; }
.iv-fact { font-family: var(--font-mono); font-size: 10px; color: var(--purple); }

.intent-fact-chip {
  display: inline-block;
  padding: 1px 7px;
  margin: 2px;
  background: rgba(63,185,80,.1);
  border: 1px solid rgba(63,185,80,.25);
  border-radius: 8px;
  font-size: 10px;
  font-family: var(--font-mono);
  color: var(--green);
}
.intent-fact-chip.missing {
  background: rgba(248,81,73,.1);
  border-color: rgba(248,81,73,.25);
  color: var(--red);
}

