/* ─── Phase 8-10: 학습 패널 ─── */
#learning-panel {
  position: fixed;
  top: 52px; right: 20px;
  width: 320px;
  max-height: 420px;
  background: var(--bg2);
  border: 1px solid var(--border);
  border-radius: 10px;
  box-shadow: 0 4px 24px rgba(0,0,0,.5);
  z-index: 300;
  display: none;
  flex-direction: column;
  overflow: hidden;
}
#learning-panel.open { display: flex; }

#learning-panel .lp-header {
  display: flex; align-items: center; gap: 8px;
  padding: 8px 14px;
  border-bottom: 1px solid var(--border);
  flex-shrink: 0;
}
#learning-panel .lp-title { font-size: 12px; font-weight: 700; flex: 1; }
#learning-panel .lp-body  { overflow-y: auto; padding: 10px 14px; flex: 1; font-size: 11px; }

.lp-section { margin-bottom: 12px; }
.lp-section-title {
  font-size: 10px; font-weight: 700; color: var(--dim);
  text-transform: uppercase; letter-spacing: .06em;
  margin-bottom: 6px;
}
.lp-stat-row {
  display: flex; justify-content: space-between;
  padding: 3px 0; border-bottom: 1px solid rgba(255,255,255,.04);
}
.lp-stat-val { font-weight: 700; color: var(--accent); font-family: var(--font-mono); }
.lp-advice {
  padding: 5px 8px; margin-bottom: 4px;
  border-radius: 6px; font-size: 11px;
  border-left: 3px solid;
  line-height: 1.5;
}
.lp-advice.high   { border-color: var(--red);    background: rgba(248,81,73,.08); }
