.lp-advice.low    { border-color: var(--dim);    background: rgba(139,148,158,.08); }
.lp-advice .lp-adv-count { font-family: var(--font-mono); font-size: 10px; opacity: .7; }
.lp-infer-chip {
  display: inline-block; padding: 1px 7px; margin: 2px;
  background: rgba(188,140,255,.1); border: 1px solid rgba(188,140,255,.25);
  border-radius: 8px; font-size: 10px; font-family: var(--font-mono); color: var(--purple);
}
.lp-empty { color: var(--dim); font-size: 11px; padding: 8px 0; text-align: center; }
.btn-learn {
  background: rgba(63,185,80,.15); color: var(--green);
  border: 1px solid rgba(63,185,80,.3);
  border-radius: 6px; padding: 4px 10px; font-size: 11px; font-weight: 700;
  cursor: pointer;
}
