  }
});

// ─── Phase 8-10: 학습 현황 패널 ──────────────────────────────

const learningPanel  = document.getElementById('learning-panel');
const learnBody      = document.getElementById('learn-body');
const learnToggle    = document.getElementById('learn-toggle');

function updateLearningPanel() {
  const stats = GLOBAL_HISTORY.stats();
  const top   = GLOBAL_HISTORY.topViolations(5);
  const nodesArr = [...editor.nodes.values()].map(v => v.def ?? v);
  const advice = getPatternAdvice(nodesArr);

  const parts = [];

  // 통계 요약
  parts.push('<div class="lp-section">');
  parts.push('<div class="lp-section-title">누적 학습 통계</div>');
  parts.push(`<div class="lp-stat-row"><span>총 수정 이력</span><span class="lp-stat-val">${stats.totalRecords}회</span></div>`);
  parts.push(`<div class="lp-stat-row"><span>수정 성공률</span><span class="lp-stat-val">${stats.successRate}%</span></div>`);
  parts.push(`<div class="lp-stat-row"><span>고유 패턴</span><span class="lp-stat-val">${stats.uniquePatterns}종</span></div>`);
  parts.push('</div>');

  // 자주 발생한 위반 패턴
  if (top.length > 0) {
    parts.push('<div class="lp-section">');
    parts.push('<div class="lp-section-title">자주 발생한 위반 패턴</div>');
    for (const v of top) {
      const [subtype, fact] = v.pattern.split(':');
      const successRate = v.count > 0 ? Math.round((v.improvedCount / v.count) * 100) : 0;
      parts.push(`<div class="lp-stat-row">
        <span style="font-family:var(--font-mono);font-size:10px">${fact}</span>
        <span class="lp-stat-val">${v.count}회 <span style="color:var(--green);font-size:10px">${successRate}%↑</span></span>
      </div>`);
    }
    parts.push('</div>');
  }

  // 현재 그래프에 대한 사전 경고
  if (advice.length > 0) {
    parts.push('<div class="lp-section">');
    parts.push('<div class="lp-section-title">현재 그래프 위험 신호</div>');
    for (const a of advice) {
      parts.push(`<div class="lp-advice ${a.severity}">${a.message}</div>`);
    }
    parts.push('</div>');
  }

  if (stats.totalRecords === 0) {
    learnBody.innerHTML = '<p class="lp-empty">아직 학습 데이터가 없습니다.<br>⚡ 자동 수정을 실행하면 기억이 쌓입니다.</p>';
    return;
  }

  learnBody.innerHTML = parts.join('');
}

learnToggle.addEventListener('click', () => {
  learningPanel.classList.toggle('open');
  if (learningPanel.classList.contains('open')) updateLearningPanel();
});

document.getElementById('learn-close-btn').addEventListener('click', () => {
  learningPanel.classList.remove('open');
});

