content.content:
   689→class RepairHistoryBrowser {
   690→  constructor(maxRecords = 500) {
   691→    this._records      = [];
   692→    this._maxRecords   = maxRecords;
   693→    this._patternIndex = new Map();  // "subtype:fact" → { count, improvedCount }
   694→    this._efficacyIndex= new Map();  // "patchType:repairHint" → { applied, improved }
   695→  }
   696→
   697→  record(sessionId, violation, patch, resultScore, previousScore) {
   698→    const improved = resultScore > previousScore;
   699→    const rec = { sessionId, timestamp: Date.now(), violation, patch, resultScore, improved };
   700→    this._records.push(rec);
   701→    if (this._records.length > this._maxRecords) this._records.shift();
   702→
   703→    // 패턴 인덱스
   704→    const pk = `${violation.nodeSubtype ?? '*'}:${violation.fact}`;
   705→    const pp = this._patternIndex.get(pk) ?? { count: 0, improvedCount: 0 };
   706→    this._patternIndex.set(pk, { count: pp.count + 1, improvedCount: pp.improvedCount + (improved ? 1 : 0), lastSeen: rec.timestamp });
   707→
   708→    // 효능 인덱스
   709→    if (patch) {
   710→      const ek = `${patch.type}:${violation.repairHint}`;
   711→      const ep = this._efficacyIndex.get(ek) ?? { applied: 0, improved: 0 };
   712→      this._efficacyIndex.set(ek, { applied: ep.applied + 1, improved: ep.improved + (improved ? 1 : 0) });
   713→    }
   714→    return rec;
   715→  }
   716→
   717→  patternCount(subtype, fact) {
   718→    return this._patternIndex.get(`${subtype ?? '*'}:${fact}`)?.count ?? 0;
   719→  }
   720→
   721→  topViolations(n = 5) {
   722→    return [...this._patternIndex.entries()]
   723→      .map(([key, v]) => ({ pattern: key, ...v }))
   724→      .sort((a, b) => b.count - a.count)
   725→      .slice(0, n);
   726→  }
   727→
   728→  patchEfficacy(patchType, repairHint) {
   729→    const e = this._efficacyIndex.get(`${patchType}:${repairHint}`);
   730→    if (!e || e.applied === 0) return 0.5;
   731→    return e.improved / e.applied;
   732→  }
   733→
   734→  stats() {
   735→    const total = this._records.length;
   736→    const improved = this._records.filter(r => r.improved).length;
   737→    return {
   738→      totalRecords:   total,
   739→      improvedCount:  improved,
   740→      successRate:    total > 0 ? Math.round((improved / total) * 100) : 0,
   741→      uniquePatterns: this._patternIndex.size,
   742→      topViolations:  this.topViolations(3),
   743→    };
   744→  }
   745→}
   746→
   747→/**
   748→ * ContractInferrer (브라우저 버전) — props + label → facts 추론
   749→ */
   750→function inferContract(node) {
   751→  const props   = node.props ?? {};
   752→  const subtype = node.subtype;
   753→  const requires = [], ensures = [], produces = [], warns = [];
   754→
   755→  if (subtype === 'input') {
   756→    if (props.type === 'email')    produces.push('form.email.filled');
   757→    if (props.type === 'password') produces.push('form.password.filled');
   758→    produces.push('data.available');
   759→  }
   760→  if (subtype === 'button') {
   761→    const label = (props.label ?? '').toLowerCase();
   762→    if (/로그인|login/.test(label))    produces.push('auth.initiated');
   763→    if (/제출|submit/.test(label))     produces.push('form.submitted');
   764→    if (/검색|search/.test(label))     produces.push('search.initiated');
   765→    if (/증가|\+|inc/.test(label))     produces.push('counter.incremented');
   766→    if (/감소|-|dec/.test(label))      produces.push('counter.decremented');
   767→    produces.push('ui.button.clickable');
   768→    warns.push('ui.button.connected');
   769→  }
