  parts.push(`<div class="lp-stat-row"><span>총 수정 이력</span><span class="lp-stat-val">${stats.totalRecords}회</span></div>`);
  parts.push(`<div class="lp-stat-row"><span>수정 성공률</span><span class="lp-stat-val">${stats.successRate}%</span></div>`);
  parts.push(`<div class="lp-stat-row"><span>고유 패턴</span><span class="lp-stat-val">${stats.uniquePatterns}종</span></div>`);
  if (stats.since) {
    parts.push(`<div class="lp-stat-row"><span>첫 기록</span><span class="lp-stat-val" style="font-size:10px">${stats.since}</span></div>`);
  }
  parts.push('</div>');

  // 자주 발생한 위반 패턴
  if (top.length > 0) {
    parts.push('<div class="lp-section">');
    parts.push('<div class="lp-section-title">자주 발생한 위반 패턴</div>');
    for (const v of top) {
      const [, fact]   = v.pattern.split(':');
      const successRate = v.count > 0 ? Math.round((v.improvedCount / v.count) * 100) : 0;
      const barWidth    = Math.max(4, successRate);
      parts.push(`<div class="lp-stat-row" style="flex-direction:column;gap:3px;align-items:stretch">
        <div style="display:flex;justify-content:space-between">
          <span style="font-family:var(--font-mono);font-size:10px;color:var(--purple)">${fact}</span>
          <span class="lp-stat-val">${v.count}회</span>
        </div>
        <div style="height:3px;background:var(--bg3);border-radius:2px;overflow:hidden">
          <div style="height:100%;width:${barWidth}%;background:var(--green);border-radius:2px"></div>
        </div>
        <div style="font-size:10px;color:var(--dim)">수정 성공 ${successRate}%</div>
      </div>`);
    }
    parts.push('</div>');
  }

  // 현재 그래프에 대한 사전 경고
  if (advice.length > 0) {
    parts.push('<div class="lp-section">');
    parts.push('<div class="lp-section-title">현재 그래프 위험 신호</div>');
    for (const a of advice) {
      parts.push(`<div class="lp-advice ${a.severity}">${a.message}</div>`);
    }
    parts.push('</div>');
  }

  // 이력 초기화 버튼
  parts.push(`<div style="margin-top:8px;text-align:center">
    <button id="learn-clear-btn" style="background:rgba(248,81,73,.1);color:var(--red);border:1px solid rgba(248,81,73,.3);border-radius:5px;padding:4px 12px;font-size:11px;cursor:pointer">
      🗑 학습 이력 초기화
    </button>
  </div>`);

  learnBody.innerHTML = parts.join('');

  // 초기화 버튼 이벤트 (동적 생성이므로 매번 바인딩)
  document.getElementById('learn-clear-btn')?.addEventListener('click', () => {
    if (confirm('학습 이력을 모두 삭제하시겠습니까?\nlocalStorage에서도 제거됩니다.')) {
      GLOBAL_HISTORY.clear();
      updateLearningPanel();
      editor._msg('학습 이력이 초기화됐습니다', 'warn');
    }
  });
}

