  ['HISTORY_STORAGE_KEY', 'localStorage 키 상수'],
  ['_persist()', '자동 저장 호출'],
  ['_restore()', '복원 메서드'],
  ['localStorage.setItem', 'setItem 호출'],
  ['localStorage.getItem', 'getItem 호출'],
  ['localStorage.removeItem', '이력 초기화'],
  ['_historyRestored', '복원 여부 플래그'],
  ['학습 이력 복원', '시작 시 복원 메시지'],
  ['학습 이력 초기화', '이력 초기화 버튼'],
  ['💾 localStorage 복원됨', '복원 배지'],
  ['첫 기록', '첫 기록 날짜 표시'],
  ['since', 'stats.since 필드'],
];
let ok = 0, fail = 0;
