// 생성 실행
async function runAIGenerate() {
  const text = aiInput.value.trim();
  if (!text) { aiInput.focus(); return; }

  aiStatus.textContent = '⏳ 노드 생성 중...';
  aiStatus.style.color = 'var(--dim)';

  try {
    const result = await aiGenerate(text);
    // 기존 노드들의 최대 X 위치 계산해서 오른쪽에 배치
    let maxX = 0;
    for (const n of editor.nodes.values()) {
      if ((n.x ?? 0) > maxX) maxX = n.x;
    }
    const offsetX = editor.nodes.size === 0 ? 80 : maxX + 250;

    // offsetX 적용
    for (const n of Object.values(result.nodes)) {
      n.position.x += (offsetX - 100);
    }

    // 노드 추가
    const idMap = {};
    for (const [oldId, n] of Object.entries(result.nodes)) {
      const nid = `n${editor.nodeIdCtr++}`;
      idMap[oldId] = nid;
      const view = new NodeView(nid, n, n.position.x, n.position.y, editor);
      editor.canvas.appendChild(view.el);
      editor.nodes.set(nid, view);
    }

    // 엣지 추가
    for (const e of result.edges) {
      const fromId = idMap[e.from], toId = idMap[e.to];
      if (fromId && toId && editor.nodes.has(fromId) && editor.nodes.has(toId)) {
        const wireId = `n${editor.nodeIdCtr++}`;
        editor.wires.set(wireId, { id:wireId, fn:fromId, fp:e.fromPort??0, tn:toId, tp:e.toPort??0 });
      }
    }

    editor._redrawAll();
    editor._updateCounts();

    aiStatus.textContent = `✅ "${result.label}" 생성 완료! ${result.nodeCount}개 노드`;
    aiStatus.style.color = 'var(--green)';
    aiInput.value = '';

    // 3초 후 상태 초기화
    setTimeout(() => { aiStatus.textContent = ''; }, 3000);
  } catch (err) {
    aiStatus.textContent = `❌ 오류: ${err.message}`;
    aiStatus.style.color = 'var(--red)';
  }
}

document.getElementById('ai-gen-btn').addEventListener('click', runAIGenerate);
aiInput.addEventListener('keydown', e => {
  if (e.key === 'Enter') runAIGenerate();
  if (e.key === 'Escape') aiPanel.classList.remove('open');
});
</script>
