fn main() -> i64 {
    return add(10, 20);
}
fn power(base: i64, exp: i64) -> i64 {
    if (exp == 0) {
        return 1;
    }
    return base * power(base, exp - 1);
}

fn fibonacci(n: i64) -> i64 {
    if (n <= 1) {
        return n;
    }
    return fibonacci(n - 1) + fibonacci(n - 2);
}

