    var p2: i64 = 0;
    var p3: i64 = 0;
    var fib_val: i64 = 0;

    p2 = power(2, 10);
    p3 = power(3, 5);
    fib_val = fibonacci(12);

    if ((p2 == 1024) && (p3 == 243)) {
        return fib_val;
    }

    return 0;
}

fn main() -> i64 {
    return generate_output();
}

